/* Malta Driving Master — Maltese Language Pack 40.7.2 FINAL LANGUAGE POLISH */
window.MDM_MT_QUESTIONS={"CARS1.2":{"question_mt":"Qabel tagħmel dawra f’forma ta’ U fit-triq, dejjem għandek:","answers_mt":["Tagħżel ger ogħla mis-soltu","Tagħti sinjal biex sewwieqa oħra jnaqqsu l-veloċità","Tħares minn fuq spalltek għal konferma finali","Tagħti sinjal ieħor minbarra l-indikaturi"],"explanation_mt":"Kontroll finali minn fuq l-ispalla jgħinek tara vetturi jew ċiklisti li jistgħu jkunu fil-angolu mejjet."},"CARS1.3":{"question_mt":"Bħala sewwieq, x'tifhem bit-terminu 'angolu mejjet'?","answers_mt":["Żona koperta mill-mera tax-xellug","Żona mhux imdawla mill-fanali ta' quddiem","Żona koperta mill-mera tal-lemin","Żona li ma tidhirx fil-mirja"],"explanation_mt":"Angolu mejjet huwa żona madwar il-vettura li ma tistax tidher fil-mirja."},"CARS1.7":{"question_mt":"Xi tfisser l-abbrevjazzjoni MSM?","answers_mt":["Mera, sinjal, manuvra","Manuvra, veloċità, mera","Mera, veloċità, manuvra","Manuvra, sinjal, mera"],"explanation_mt":"MSM hija s-sekwenza normali Mera–Sinjal–Manuvra."},"CARS1.9":{"question_mt":"Meta tkun qed issegwi vettura kbira, għandek iżżomm distanza sigura warajha għax:","answers_mt":["Tgħinek tibqa' barra mir-riħ","Tgħin lill-vettura kbira tieqaf aktar faċilment","Tippermetti lis-sewwieq jarak fil-mera","Tippermettilek iddur mal-kantunieri aktar malajr"],"explanation_mt":"Meta żżomm lura tibqa' viżibbli fil-mirja tas-sewwieq tal-vettura kbira u jkollok veduta aħjar tat-triq quddiemek."},"CARS1.10":{"question_mt":"F'liema sitwazzjoni għandek tevita li taqbeż vettura oħra?","answers_mt":["Fi triq b'limitu ta' 50 km/h","Fi triq b’direzzjoni waħda","Eżatt wara liwja","Meta tkun qed toqrob lejn niżla moħbija fit-triq"],"explanation_mt":"Niżla fit-triq tista' taħbi traffiku ġej minn quddiem, għalhekk il-qbiż ma jkunx sigur."},"CARS1.12":{"question_mt":"Għaliex m'għandekx tuża mowbajl waqt is-sewqan?","answers_mt":["Ir-riċezzjoni tkun ħażina meta l-magna tkun mixgħula","Tista' ssuq b'mod sigur b'id waħda","Jista' jtelliflek l-attenzjoni mit-triq quddiemek","Huwa permess meta ma jkun hemm l-ebda traffiku viċin"],"explanation_mt":"L-użu tat-telefon jista' jtelliflek l-attenzjoni u jnaqqas il-kontroll tiegħek fuq il-vettura."},"CARS1.13":{"question_mt":"L-użu ta' telefon bla idejn waqt is-sewqan:","answers_mt":["Huwa tajjeb ħafna għas-sigurtà fit-triq","Jista' jtelliflek l-attenzjoni mit-triq","Huwa rakkomandat mill-Kodiċi tat-Triq","Huwa sigur sakemm tnaqqas il-veloċità"],"explanation_mt":"Anke l-użu bla idejn joħloq distrazzjoni mentali."},"CARS1.18":{"question_mt":"Fi triq dejqa tal-kampanja, kif għandek taqbeż ċiklist?","answers_mt":["Malajr, waqt li ddoqq il-ħorn","Malajr, waqt li tħalli ħafna spazju","Bil-mod, waqt li tħalli ħafna spazju","Bil-mod, waqt li ddoqq il-ħorn"],"explanation_mt":"Aqbeż bil-mod u ħalli ħafna spazju għax iċ-ċiklisti jistgħu jitbandlu jew jiddevjaw f'daqqa."},"CARS1.24":{"question_mt":"Qed issuq fid-dlam u d-dwal ta' vettura ġejja minn quddiem jgħammxuk. X'għandek tagħmel?","answers_mt":["Naqqas il-veloċità jew ieqaf","Niżżel il-viżiera tax-xemx","Ixgħel u itfi l-fanali ta’ quddiem biex tagħti sinjal","Agħlaq għajnejk"],"explanation_mt":"Naqqas il-veloċità u, jekk meħtieġ, ieqaf sakemm terġa' tara ċar."},"CARS1.25":{"question_mt":"Qed issuq għall-għabex. Meta għandhom jinxtegħlu d-dwal tiegħek? Agħżel 2 tweġibiet.","answers_mt":["Biex oħrajn ikunu jistgħu jarawk","Anke meta d-dwal tat-triq ikunu mixgħula","Biss meta d-dwal tat-triq ikunu mixgħula","Biss meta oħrajn ikunu xegħluhom"],"explanation_mt":"Għall-għabex, uża d-dwal biex tagħmel lilek innifsek viżibbli, anke fi toroq imdawla."},"CARS2.4":{"question_mt":"Qed toqrob lejn qsim taż-żebra u hemm nies mexjin jistennew biex jaqsmu. Għandek:","answers_mt":["Tagħmlilhom sinjal b'idejk biex jaqsmu","Tnaqqas il-veloċità u tipprepara biex tieqaf","Tixgħel u titfi l-fanali ta’ quddiem","Iċċedi biss lill-anzjani"],"explanation_mt":"Avviċina bil-mod u kun lest li tieqaf għan-nies mexjin."},"CARS2.6":{"question_mt":"Għaliex qatt m'għandek tagħmel sinjal jew tħeġġeġ lin-nies biex jaqsmu f'qsim pedonali?","answers_mt":["Jista' jkun hemm vettura oħra ġejja","Jistgħu ma jkunux lesti","Ikun aktar sigur għalik li tkompli","Jistgħu ma jkunux qed iħarsu"],"explanation_mt":"Vettura oħra tista' toqrob minn direzzjoni li l-persuna miexja ma tkunx tista' tara."},"CARS2.9":{"question_mt":"Meta tista' tuża r-regola taż-żewġ sekondi?","answers_mt":["Meta toħroġ għal triq imxarrba","Biex iżżomm distanza sigura mill-vettura ta' quddiem","Qabel tuża r-rutina MSM","Qabel terġa' tqabbad magna li waqfet"],"explanation_mt":"Ir-regola taż-żewġ sekondi tintuża biex tkejjel distanza ta' sigurtà mill-vettura ta' quddiem f'kundizzjonijiet tajbin."},"CARS2.14":{"question_mt":"Għaliex mhux għaqli li ssegwi vettura kbira wisq mill-qrib? Agħżel 2 tweġibiet.","answers_mt":["Il-magna tiegħek tisħon iżżejjed","Il-veduta tiegħek 'il quddiem tonqos","Il-brejkijiet tiegħek jisħnu żżejjed","Is-sewwieq ma jkunx jista' jarak fil-mirja"],"explanation_mt":"Titlef il-veduta tat-triq quddiemek u tista' tkun fil-angolu mejjet tal-vettura kbira."},"CARS2.17":{"question_mt":"Fi triq imxarrba u tiżloq, x'inhu l-intervall minimu ta' ħin li għandek tħalli?","answers_mt":["Tliet sekondi","Żewġ sekondi","Sekonda waħda","Erba' sekondi"],"explanation_mt":"F'kundizzjonijiet imxarrba, żomm mill-inqas erba' sekondi bejn il-vettura tiegħek u dik ta' quddiem."},"CARS2.19":{"question_mt":"Is-sewwieq ta' warajk qed isegwik wisq mill-qrib. X'għandek tagħmel?","answers_mt":["Tersaq qrib il-linja tan-nofs","Tnaqqas il-veloċità gradwalment u żżid id-distanza quddiemek","Tagħmillu sinjal biex jaqbżek","Tinjorah"],"explanation_mt":"Meta żżid l-ispazju quddiemek ikollok aktar lok biex tibbrejkja bil-mod u b'mod progressiv."},"CARS2.20":{"question_mt":"Qed issuq fil-limitu legali tal-veloċità. Vettura tersaq malajr warajk u tixgħel u titfi l-fanali ta’ quddiem. Għandek:","answers_mt":["Ma tħallihiex taqbżek","Tmiss il-brejkijiet","Taċċellera","Tħalli l-vettura taqbżek"],"explanation_mt":"Tikkompetix u timblukkax il-vettura; ħalliha tgħaddi meta jkun sigur."},"CARS2.22":{"question_mt":"Meta huwa permess li taqbeż il-limitu massimu tal-veloċità?","answers_mt":["Meta t-triq tkun vojta","Qatt","Meta tkun qed taqbeż vettura oħra","Bejn nofsillejl u s-6 ta' filgħodu"],"explanation_mt":"Il-limitu massimu tal-veloċità m'għandux jinqabeż."},"CARS2.30":{"question_mt":"Liema vetturi jistgħu jużaw dwal blu li jteptpu? Agħżel 2 tweġibiet.","answers_mt":["Tabib fuq sejħa","Vettura tal-għassa tal-pulizija","Ambulanza","Vettura ta' rkupru għal ħsarat","Vettura tal-manutenzjoni tat-toroq"],"explanation_mt":"Il-Pulizija u l-ambulanzi jistgħu jużaw dwal blu li jteptpu għal interventi ta' emerġenza."},"CARS2.31":{"question_mt":"Ambulanza b'dawl blu li jteptep qed issegwik. X'għandek tagħmel?","answers_mt":["Twarrab mal-ġenb hekk kif ikun sigur","Tibbrejkja f'daqqa f'nofs it-triq","Iżżomm l-istess veloċità u direzzjoni","Taċċellera biex titbiegħed"],"explanation_mt":"Agħtiha triq malajr iżda b'mod sigur; toħloqx periklu ieħor."},"CARS2.32":{"question_mt":"Xarabank wieqfa f'waqfa tax-xarabank qed tagħti sinjal lejn il-lemin. X'għandek tagħmel?","answers_mt":["Tnaqqas il-veloċità u ddoqq il-ħorn","Tnaqqas il-veloċità u ċċedi jekk ikun sigur","Iddoqq il-ħorn u tkompli","Tixgħel u titfi l-fanali ta’ quddiem u tnaqqas il-veloċità"],"explanation_mt":"Agħti lix-xarabank biżżejjed spazju biex toħroġ mill-waqfa meta jkun sigur."},"CARS2.34":{"question_mt":"Għaliex għandek tuża l-ħorn?","answers_mt":["Biex tavża lil oħrajn bil-preżenza tiegħek","Biex turi d-dwejjaq tiegħek","Biex issellem lil utenti oħra tat-triq","Biex tikseb il-prijorità"],"explanation_mt":"Il-ħorn huwa mezz ta' twissija, mhux mod biex tilmenta jew titlob il-prijorità."},"CARS3.4":{"question_mt":"Liema ŻEWĠ affarijiet jiġu affettwati ħażin jekk il-pressjoni tat-tajers tkun baxxa wisq?","answers_mt":["L-istering","L-ibbrejkjar","Il-parkeġġ","It-tibdil tal-gerijiet"],"explanation_mt":"Pressjoni baxxa fit-tajers tnaqqas ir-rispons tal-istering u l-prestazzjoni tal-ibbrejkjar."},"CARS3.8":{"question_mt":"Kemm ta' spiss għandha tiġi ċċekkjata l-pressjoni tat-tajers, mill-inqas?","answers_mt":["F'kull eżami VRT","Darba fil-ġimgħa","Darba fix-xahar","F'kull servizz"],"explanation_mt":"Kontroll ta' kull ġimgħa jgħin biex tinżamm is-sigurtà u l-effiċjenza tal-fjuwil."},"CARS3.18":{"question_mt":"Meta għandek tuża l-fanali baxxi matul il-ġurnata?","answers_mt":["Meta tipparkja","Fi toroq dojoq","Meta l-viżibbiltà tkun ħażina","Il-ħin kollu"],"explanation_mt":"Il-fanali baxxi jagħmluk aktar viżibbli mingħajr ma jgħammxu lil oħrajn meta l-viżibbiltà tkun ħażina."},"LPOINTS1.92":{"question_mt":"Għaliex jiġu installati ħotob fit-triq u kurvi artifiċjali għat-tnaqqis tal-veloċità?","answers_mt":["Biex tiġi ċċekkjata s-sospensjoni tiegħek","Biex tiżdied il-veloċità tat-traffiku","Biex titnaqqas il-veloċità tat-traffiku","Biex jinħolqu spazji għall-parkeġġ"],"explanation_mt":"Il-ħotob fit-triq u l-kurvi artifiċjali huma miżuri biex inaqqsu l-veloċità tat-traffiku."},"LPOINTS1.93":{"question_mt":"Qed toqrob lejn salib it-toroq b'sinjal STOP. Fejn għandek tieqaf?","answers_mt":["Ħames metri wara s-salib it-toroq","Ħames metri qabel is-salib it-toroq","Qabel il-marka tal-karreġġjata fit-tarf tat-triq","F'nofs is-salib it-toroq"],"explanation_mt":"Waqqaf qabel il-linja ta’ waqfien jew il-marka tal-karreġġjata fit-tarf tat-triq."},"LPOINTS1.97":{"question_mt":"X'għandek tagħmel qabel tibdel il-korsija?","answers_mt":["Tagħti sinjal għal żewġ sekondi u timxi malajr","L-ewwel iżżid il-veloċità","Tiċċekkja l-mirja, tagħti sinjal u tħares minn fuq spallejk","Iddoqq il-ħorn"],"explanation_mt":"Uża l-mirja u s-sinjali u ċċekkja l-angolu mejjet billi tħares minn fuq spallejk."},"LPOINTS1.98":{"question_mt":"Min hu responsabbli biex jiżgura li vettura ma tkunx mgħobbija żżejjed?","answers_mt":["Il-passiġġieri","Is-sewwieq","Sid il-vettura biss","Il-kumpanija tal-assigurazzjoni"],"explanation_mt":"Is-sewwieq huwa responsabbli biex jiżgura li l-vettura ma tkunx mgħobbija żżejjed."},"LPOINTS1.99":{"question_mt":"Meta huwa meħtieġ li tagħti sinjal?","answers_mt":["Mhux dejjem meta ddur","Qabel iddur jew tibdel il-korsija","Biss matul il-ġurnata","Biss meta vettura oħra tkun viċin"],"explanation_mt":"Agħti sinjal minn kmieni qabel iddur jew tibdel il-korsija."},"LPOINTS1.100":{"question_mt":"X'jista' jwassal biex l-istering isir tqil?","answers_mt":["Tajers minfuħin iżżejjed","Tajers mhux minfuħin biżżejjed","Sewqan fix-xita","Reċipjent tal-fjuwil mimli"],"explanation_mt":"Tajers mhux minfuħin biżżejjed iżidu l-isforz meħtieġ biex iddawwar l-istering u jaffettwaw il-kontroll tal-vettura."},"LPOINTS1.103":{"question_mt":"Meta tista' tidħol f'salib it-toroq b'kaxxa safra?","answers_mt":["Meta tkun se ddur lejn ix-xellug","Meta l-ħruġ tiegħek ikun liberu","Meta jkun hemm inqas minn żewġ vetturi quddiemek","Kull meta d-dawl ikun aħdar"],"explanation_mt":"Tidħolx f'salib it-toroq b'kaxxa safra sakemm il-ħruġ tiegħek ma jkunx liberu."},"LPOINTS1.106":{"question_mt":"Fejn għandek tevita li taqbeż vettura oħra?","answers_mt":["Fi triq b'limitu ta' 50 km/h","Fi triq b’direzzjoni waħda","Meta tkun qed toqrob lejn liwja","F'karreġġjata doppja"],"explanation_mt":"Evita li taqbeż meta tkun qed toqrob lejn liwja għax il-viżibilità tiegħek tkun limitata."},"LPOINTS1.107":{"question_mt":"X'għandek tagħmel jekk sewwieq ieħor jaqbżek?","answers_mt":["Tibqa' kalm u tkompli ssuq","Terġa' taqbżu","Tgħajjatlu","Issuq qrib ħafna warajh"],"explanation_mt":"Ibqa' kalm, tirritaljax u żżidx il-veloċità."},"LPOINTS1.108":{"question_mt":"X'inhu l-għan ewlieni tal-ħorn?","answers_mt":["Biex iċċanfar lil xi ħadd","Biex twissi lil utenti oħra tat-triq bil-preżenza tiegħek","Biex issellem lil xi ħadd li taf","Biex it-traffiku jimxi aktar malajr"],"explanation_mt":"Il-ħorn huwa mezz ta' twissija biex tavża lil oħrajn bil-preżenza tiegħek."},"LPOINTS1.110":{"question_mt":"X'inhi raqda qasira involontarja?","answers_mt":["Episodju temporanju ta' rqad jew ngħas","Torqod fis-sedil ta' wara","Nagħsa qasira f'lukanda","Pawża ta' mistrieħ ippjanata"],"explanation_mt":"Raqda qasira involontarja hija episodju qasir ħafna u involontarju ta' rqad jew telf ta' attenzjoni."},"LPOINTS1.111":{"question_mt":"X'għandek tagħmel jekk tkun għajjien wisq biex issuq?","answers_mt":["Tuża t-trasport pubbliku jew titlob lil xi ħadd iwasslek","Issuq aktar malajr biex tasal id-dar","Tixrob kafè qawwi u ssuq minnufih","Tiftaħ it-tieqa u tkompli"],"explanation_mt":"Issuqx meta tkun għajjien iżżejjed; uża mezz ieħor ta' trasport."},"LPOINTS1.114":{"question_mt":"X'inhu sewqan difensiv?","answers_mt":["Sewqan sigur minkejja l-kundizzjonijiet u l-azzjonijiet ta' oħrajn","Dejjem iċċedi","Tuża sinjali STOP u qsim taż-żebra","Dejjem issuq bil-mod"],"explanation_mt":"Sewqan difensiv ifisser li tantiċipa l-perikli u tipproteġi lilek innifsek mill-iżbalji ta' oħrajn."},"LPOINTS1.115":{"question_mt":"Sewwieq għandu jevita d-distrazzjonijiet u jikkonċentra fuq it-triq?","answers_mt":["Iva","Biss meta jkun stressjat","Le","Biss fuq awtostradi"],"explanation_mt":"Sewwieq għandu jevita kull distrazzjoni u jżomm l-attenzjoni sħiħa fuq is-sewqan."},"LPOINTS1.118":{"question_mt":"Kif għandek issuq f'temp ħażin jew f'kundizzjonijiet perikolużi?","answers_mt":["B'aktar kawtela","Aktar malajr biex tasal qabel","Tevita biss it-toroq ewlenin","Iddoqq il-ħorn kontinwament"],"explanation_mt":"Naqqas il-veloċità, żid id-distanza u ssuq b'aktar kawtela."},"LPOINTS1.123":{"question_mt":"X'għandek tagħmel meta t-triq tkun mgħarrqa ħafna?","answers_mt":["Tkompli normalment","Tippjana minn qabel u tevita ż-żona mgħarrqa","Tgħaddi mill-ilma b'veloċità għolja","Issegwi mill-qrib il-vettura ta' quddiem"],"explanation_mt":"Fejn possibbli, evita żoni mgħarrqa ħafna għax il-fond tal-ilma u l-perikli jistgħu ma jkunux magħrufa."},"LPOINTS1.124":{"question_mt":"Jekk xi ħadd iweġġa' f'inċident, x'għandu jagħmel is-sewwieq?","answers_mt":["Jitlaq minnufih","Joffri sigarett","Iċempel 112 u jagħti assistenza","Iċempel 911"],"explanation_mt":"Ċempel lis-servizzi ta' emerġenza fuq 112 u agħti assistenza raġonevoli."},"LPOINTS1.134":{"question_mt":"Għandek tagħti sinjal lil sewwieqa oħra li biħsiebek tipparkja?","answers_mt":["Dejjem","Kultant","Qatt","Biss bil-lejl"],"explanation_mt":"Agħti sinjal ċar u minn kmieni qabel tipparkja."},"LPOINTS1.171":{"question_mt":"Kif għandek issuq minn ġo mina?","answers_mt":["Taċċellera u tibqa’ fl-istess korsija","Tixgħel id-dwal u tibqa’ fl-istess korsija","Tibdel il-korsija kull meta jkun possibbli","Tuża d-dwal ta’ emerġenza matul il-mina kollha"],"explanation_mt":"Uża d-dwal u ibqa' fil-korsija tiegħek matul il-mina kollha, sakemm ma tingħatax struzzjoni mod ieħor."},"LPOINTS1.172":{"question_mt":"X'għandek tagħmel meta vettura twila tkun qed iddur ma' rotonda?","answers_mt":["Tagħtiha ħafna spazju","Taqbiżha","Iddoqq il-ħorn","Issuq maġenbha"],"explanation_mt":"Vetturi twal jeħtieġu spazju żejjed u jistgħu jkollhom jużaw aktar minn korsija waħda."},"LPOINTS1.175":{"question_mt":"Kemm ta' spiss għandha tiġi ċċekkjata l-pressjoni tat-tajers, mill-inqas?","answers_mt":["Kull ġimgħa","Kuljum","Kull xahar","Darba fis-sena"],"explanation_mt":"Il-materjal ta' studju jirrakkomanda li l-pressjoni tat-tajers tiġi ċċekkjata mill-inqas darba fil-ġimgħa."},"LPOINTS1.176":{"question_mt":"X’kulur għandhom ikunu d-dwal ta’ emerġenza?","answers_mt":["Ħomor","Sofor","Ambra","Bojod"],"explanation_mt":"L-indikaturi ta’ emerġenza jteptpu b’kulur ambra."},"LPOINTS1.182":{"question_mt":"Kemm-il metru għandhom jitħallew liberi meta tipparkja qrib kantuniera jew salib it-toroq?","answers_mt":["5 metri","4 metri","7 metri","12-il metru"],"explanation_mt":"Ħalli mill-inqas ħames metri liberi ħdejn kantuniera jew salib it-toroq."},"LPOINTS1.183":{"question_mt":"Kemm-il metru għandhom jitħallew liberi fuq kull naħa ta' waqfa tax-xarabank jew waqfa tal-linja?","answers_mt":["12-il metru","15-il metru","7 metri","5 metri"],"explanation_mt":"Ħalli tnax-il metru liberi fuq kull naħa ta' waqfa tax-xarabank jew waqfa tal-linja."},"LPOINTS1.184":{"question_mt":"Qrib liema post normalment ikun ristrett l-użu tal-ħorn?","answers_mt":["Mużewijiet tal-arti","Siti storiċi","Sptarijiet","Ċentri kummerċjali"],"explanation_mt":"L-użu tal-ħorn normalment ikun ristrett qrib sptarijiet biex jiġi evitat storbju bla bżonn."},"CARS3.23":{"question_mt":"Kif jista' sewwieq jgħin lill-ambjent? Agħżel 3 tweġibiet.","answers_mt":["Jagħmel manutenzjoni xierqa tal-vettura","Jaċċellera bil-mod u b'mod progressiv","Jaċċellera b'mod qawwi","Isuq aktar malajr","Inaqqas il-veloċità","Juża fjuwil biċ-ċomb"],"explanation_mt":"Manutenzjoni tajba, aċċelerazzjoni ġentili u veloċità aktar baxxa jnaqqsu l-konsum tal-fjuwil u l-emissjonijiet."},"CARS3.27":{"question_mt":"Il-vetturi bil-mutur jistgħu jagħmlu ħsara lill-ambjent u jwasslu għal: Agħżel 3 tweġibiet.","answers_mt":["Konsum tar-riżorsi naturali","Ħsara lill-bini","Inqas użu ta' vetturi elettriċi","Titjib fit-trasport pubbliku","Tnaqqis tar-riskji għas-saħħa","Tniġġis tal-arja"],"explanation_mt":"It-trasport bit-triq jikkonsma riżorsi, jikkontribwixxi għat-tniġġis tal-arja u jista' jagħmel ħsara lill-bini."},"CARS3.28":{"question_mt":"Biex tnaqqas il-ħsara ambjentali kkawżata mill-vettura tiegħek, x'għandek tagħmel? Agħżel 3 tweġibiet.","answers_mt":["Tuża toroq traffikużi","Tippjana sew minn qabel","Tibbrejkja fil-ħin","Tevita aċċelerazzjoni qawwija","Tuża toroq sekondarji dojoq"],"explanation_mt":"Sewqan ippjanat u bla skossi jnaqqas il-konsum tal-fjuwil u l-emissjonijiet."},"CARS3.38":{"question_mt":"Meta m'għandekx iddoqq il-ħorn f'żona mibnija?","answers_mt":["Bejn il-11:30 ta' billejl u s-7:00 ta' filgħodu","Fi kwalunkwe ħin","Bejn l-10:00 ta' billejl u s-6:00 ta' filgħodu","Bejn il-11:00 ta' billejl u s-6:00 ta' filgħodu"],"explanation_mt":"Il-ġabra attwali tal-mistoqsijiet jgħid li f'żona mibnija l-ħorn m'għandux jintuża bejn il-11 ta' billejl u s-6 ta' filgħodu, ħlief meta jkun meħtieġ biex jiġi evitat periklu."},"CARS4.7":{"question_mt":"Meta ssuq fiċ-ċpar, liema miżuri huma korretti? Agħżel 3 tweġibiet.","answers_mt":["Tuża biss id-dwal tal-pożizzjoni","Tuża l-fanali baxxi","Tibqa' qrib il-karozza ta' quddiem","Tnaqqas il-veloċità","Tuża l-fanali għoljin","Tħalli aktar ħin għall-vjaġġ"],"explanation_mt":"Fiċ-ċpar uża l-fanali baxxi, naqqas il-veloċità u ħalli aktar ħin għall-vjaġġ."},"CARS4.14":{"question_mt":"F'xita qawwija l-istering f'daqqa jsir ħafif ħafna. X'għandek tagħmel?","answers_mt":["Tibbrejkja b'saħħa","Taċċellera bil-mod","Iddawwar lejn il-ġenb","Tneħħi saqajk bil-mod mill-aċċeleratur"],"explanation_mt":"Istering ħafif jista’ jindika żliq fuq saff ta’ ilma; neħħi l-pressjoni mill-aċċeleratur b’mod gradwali."},"CARS4.20":{"question_mt":"F'salib it-toroq b'viżibbiltà limitata, x'għandek tagħmel?","answers_mt":["Tkun lest li titlaq malajr","Timxi 'l quddiem bil-mod waqt li tħares lejn ix-xellug","Timxi 'l quddiem bil-mod waqt li tħares lejn il-lemin","Timxi 'l quddiem bil-mod waqt li tħares fiż-żewġ direzzjonijiet"],"explanation_mt":"Avvanza bil-mod u b'attenzjoni waqt li tiċċekkja ż-żewġ direzzjonijiet."},"CARS4.30":{"question_mt":"Meta m'għandekx taqbeż vettura oħra? Agħżel 3 tweġibiet.","answers_mt":["Meta tkun tiela' għolja twila","Fi triq b’direzzjoni waħda","Meta l-veduta quddiemek tkun imblukkata","Meta tkun qed toqrob lejn salib it-toroq","Meta biħsiebek iddur lejn ix-xellug ftit wara"],"explanation_mt":"Taqbiżx jekk ma jkollokx veduta ċara, qrib salib it-toroq jew qabel iddur lejn ix-xellug."},"CARS5.6":{"question_mt":"Liema TLIET effetti jirriżultaw mix-xorb tal-alkoħol u s-sewqan?","answers_mt":["Inqas kontroll","Ġudizzju ħażin tal-veloċità","Aktar għarfien tal-periklu","Reazzjonijiet aktar mgħaġġla","Sens falz ta' kunfidenza"],"explanation_mt":"L-alkoħol inaqqas il-kontroll u l-ġudizzju u joħloq sens falz ta' kunfidenza."},"CARS5.10":{"question_mt":"Minbarra l-alkoħol, x'jista' jaffettwa serjament il-konċentrazzjoni waqt is-sewqan? Agħżel 3 tweġibiet.","answers_mt":["Mużika għolja","Għeja","Lentijiet tal-kuntatt","Ħġieġ ikkulurit","Drogi"],"explanation_mt":"Mużika għolja, għeja u drogi jistgħu jnaqqsu serjament il-konċentrazzjoni."},"CARS1.14":{"question_mt":"L-użu ta' telefon bla idejn x'aktarx li:","answers_mt":["Inaqqas il-veduta tiegħek","Iżid il-konċentrazzjoni tiegħek","Itejjeb is-sigurtà tiegħek","Jtelliflek l-attenzjoni"],"explanation_mt":"Konversazzjoni bla idejn xorta tista' tfixkillek moħħok mis-sewqan."},"CARS1.15":{"question_mt":"L-użu ta' mowbajl waqt li tkun qed issuq:","answers_mt":["Jaffettwa l-vettura tiegħek","Inaqqas il-kamp viżiv tiegħek","Jista' jtelliflek l-attenzjoni mit-triq","Huwa aċċettabbli f'vettura b'istering assistit"],"explanation_mt":"L-użu tal-mowbajl jista' jneħħilek l-attenzjoni mit-triq."},"CARS1.19":{"question_mt":"Biex twieġeb il-mowbajl waqt is-sewqan għandek:","answers_mt":["Tnaqqas il-veloċità u tħalli lil oħrajn jaqbżuk","Tieqaf f'post xieraq u konvenjenti","Iżżomm it-telefonata qasira kemm jista' jkun","Tnaqqas il-veloċità tkun fejn tkun"],"explanation_mt":"Ieqaf b'mod sigur qabel twieġeb jew tagħmel telefonata."},"CARS1.23":{"question_mt":"Għaliex għandek tkun ipparkjat qabel tuża mowbajl?","answers_mt":["Għax l-elettriku tal-karozza jiġi affettwat","Biex il-kontroll tal-vettura tiegħek ma jiġix affettwat","Biex tkun tista' ssir konversazzjoni tajba","Għax ir-riċezzjoni tkun aħjar meta tkun wieqaf"],"explanation_mt":"L-użu tat-telefon waqt li l-vettura tkun miexja jista' jnaqqas il-kontroll tiegħek fuqha."},"CARS1.26":{"question_mt":"Biex taqbeż b'mod sigur, liema waħda minn dawn tapplika?","answers_mt":["Iċċekkja l-veloċità u l-pożizzjoni tat-traffiku warajk","Iddur f'daqqa madwar il-vettura","Tersaq qrib ħafna warajha qabel toħroġ","Terġa' tidħol fil-korsija f'daqqa wara li taqbiżha"],"explanation_mt":"Qabel taqbeż, iċċekkja l-mirja u l-veloċità u l-pożizzjoni tat-traffiku warajk."},"CARS2.1":{"question_mt":"Qsim pedonali kkontrollat bid-dwal li jaqsam it-triq f'linja dritta u għandu gżira tat-traffiku fin-nofs għandu jitqies bħala:","answers_mt":["Żewġ qsim fid-dlam","Qsim wieħed sħiħ","Żewġ qsim separati","Qsim wieħed biss matul il-jum"],"explanation_mt":"Qsim pedonali kkontrollat bid-dwal dritt b'gżira ċentrali jitqies bħala qsim wieħed sħiħ."},"CARS2.2":{"question_mt":"F'qsim pedonali kkontrollat bid-dwal, xi jfisser id-dawl ambra? Agħżel 2 tweġibiet.","answers_mt":["Ċedi lin-nies li diġà qegħdin fuq il-qsim","Ieqaf u stenna d-dawl aħmar","Ċedi lin-nies li qed jistennew biex jaqsmu","Ieqaf u stenna d-dawl aħdar"],"explanation_mt":"Id-dawl ambra jfisser li għandek tieqaf, u trid iċċedi lin-nies li diġà qegħdin jaqsmu."},"CARS2.3":{"question_mt":"Qed toqrob lejn qsim pedonali kkontrollat bid-dwal u d-dawl ambra huwa mixgħul. Trid: Agħżel 2 tweġibiet.","answers_mt":["Ma tiċċaqlaqx sakemm jidher id-dawl aħdar","Tħeġġeġ lin-nies biex jaqsmu","Tkompli ssuq","Tieqaf u tistenna d-dawl aħmar anke jekk il-qsim ikun vojt"],"explanation_mt":"Tkomplix minn sinjal ambra; ieqaf u stenna s-sinjal xieraq."},"CARS2.5":{"question_mt":"Waqaft f'qsim taż-żebra biex tħalli lin-nies jaqsmu. Għandek:","answers_mt":["Tistenna sakemm ikunu qasmu","Tagħmlilhom sinjal biex jaqsmu","Tistenna waqt li tgħolli r-revs tal-magna","Tmexxi l-vettura ftit ftit 'il quddiem"],"explanation_mt":"Ibqa' wieqaf u paċenzjuż sakemm in-nies ikunu temmew il-qsim."},"CARS2.7":{"question_mt":"F'qsim taż-żebra għandek:","answers_mt":["Tagħmel sinjal lin-nies biex jaqsmu","Tipparkja fuq il-linji żigżag","Dejjem iżżommu vojt meta t-traffiku jkun f'kju","Tgħolli r-revs tal-magna biex tgħaġġel lin-nies"],"explanation_mt":"Qatt timblokka qsim pedonali meta t-traffiku jkun f'kju."},"CARS2.8":{"question_mt":"Waqaft għal nies li kienu qed jistennew f'qsim taż-żebra, iżda ma bdewx jaqsmu. X'għandek tagħmel?","answers_mt":["Kun paċenzjuż u stenna","Tagħmlilhom sinjal biex jaqsmu","Kompli ssuq","Iddoqq il-ħorn"],"explanation_mt":"Tpoġġix pressjoni fuq in-nies; ibqa' paċenzjuż u stenna."},"CARS2.12":{"question_mt":"Meta tkun qed issegwi vettura oħra fit-triq, x'm'għandekx tagħmel?","answers_mt":["Issuq bir-dwal taċ-ċpar ta’ wara mitfija","Tagħmel marċ lura għal ġo spazju tal-parkeġġ","Issegwi l-vettura wisq mill-qrib","Tħares fil-mera ta' wara"],"explanation_mt":"Meta ssegwi wisq mill-qrib ma tħallix spazju u ħin biżżejjed biex tieqaf."},"CARS2.26":{"question_mt":"Trakk tqil qed jieħu ħafna ħin biex jaqbżek. X'għandek tagħmel?","answers_mt":["Tibdel id-direzzjoni","Tnaqqas il-veloċità","Iżżomm l-istess veloċità","Taċċellera"],"explanation_mt":"Naqqas il-veloċità biex tgħin lit-trakk itemm il-manuvra tal-qbiż b'mod sigur."},"CARS2.33":{"question_mt":"Għandek tixgħel u titfi l-fanali ta’ quddiem lejn utenti oħra tat-triq biss:","answers_mt":["Biex tgħidilhom li għandek il-prijorità","Biex turi li se tagħmel marċ lura","Biex turi li qed iċċedi","Biex tavżahom li int hemm"],"explanation_mt":"It-teptip tal-fanali ta’ quddiem għandu jintuża biss biex javża lil oħrajn bil-preżenza tiegħek."},"CARS2.36":{"question_mt":"Int fi triq b’direzzjoni waħda u trid iddur lejn il-lemin. Fejn għandek tqiegħed il-vettura?","answers_mt":["Ftit fuq ix-xellug tal-linja tan-nofs","Fi kwalunkwe korsija skont it-traffiku","Fil-korsija tax-xellug","Kemm jista' jkun qrib in-naħa tal-lemin, b'mod sigur"],"explanation_mt":"Fi triq b’direzzjoni waħda, qabel iddur lejn il-lemin poġġi ruħek qrib in-naħa tal-lemin."},"CARS2.37":{"question_mt":"Għaliex għandek tieħu l-pożizzjoni korretta minn kmieni qabel iddur lejn il-lemin?","answers_mt":["Biex tħalli lis-sewwieqa jaqbżuk min-naħa tal-lemin","Biex ikollok veduta aħjar fit-triq li se tidħol fiha","Biex tgħin lil oħrajn jifhmu x'biħsiebek tagħmel","Biex tħalli lil oħrajn joħorġu quddiemek"],"explanation_mt":"Pożizzjonament korrett u bikri jikkomunika b'mod ċar l-intenzjoni tiegħek."},"CARS2.41":{"question_mt":"Meta għandek tagħti sinjali? Agħżel 2 tweġibiet.","answers_mt":["Wara li tiċċekkja li huwa sigur, qabel tibdel id-direzzjoni, iddur, tieqaf jew titlaq","Biss meta tidħol f'karreġġjata doppja","Kull meta utenti oħra tat-triq jew nies mexjin jistgħu jibbenefikaw milli jkunu jafu x'biħsiebek tagħmel","Biss fid-dlam jew f'temp ħażin","Biex tikseb prijorità fuq traffiku ieħor"],"explanation_mt":"Agħti sinjal wara li tiċċekkja li huwa sigur u kull meta utenti oħra tat-triq jistgħu jibbenefikaw minnu."},"CARS3.1":{"question_mt":"Liema fluwidu jkun perikoluż jekk il-livell tiegħu jitħalla jinżel wisq?","answers_mt":["Likwidu li jkessaħ ir-radjatur","Likwidu tal-brejkijiet","Ilma tal-batterija","Likwidu kontra l-iffriżar"],"explanation_mt":"Livell baxx tal-likwidu tal-brejkijiet jista’ jindika ħsara u jista’ jaffettwa serjament l-ibbrejkjar."},"CARS3.7":{"question_mt":"Meta għandha tiġi ċċekkjata l-pressjoni tat-tajers?","answers_mt":["Meta t-tajers ikunu sħan","Wara sewqan b'veloċità għolja","Wara vjaġġ twil","Meta t-tajers ikunu kesħin"],"explanation_mt":"Il-pressjoni tat-tajers għandha titkejjel meta t-tajers ikunu kesħin."},"CARS3.9":{"question_mt":"Is-sewqan b'tajers minfuħin inqas milli suppost jista' jaffettwa: Agħżel 2 tweġibiet.","answers_mt":["Il-pressjoni taż-żejt","L-ibbrejkjar","Il-konsum tal-fjuwil","It-temperatura tal-magna"],"explanation_mt":"Tajers minfuħin inqas milli suppost jagħmlu l-ibbrejkjar agħar u jżidu l-konsum tal-fjuwil."},"CARS3.29":{"question_mt":"Tgħin lill-ambjent jekk:","answers_mt":["Taċċellera u tibbrejkja b'mod qawwi","Issuq kontinwament biċ-ċowk kollu","Tnaqqas il-pressjoni tat-tajers","Timxi jew tuża rota meta tista'"],"explanation_mt":"Il-mixi jew l-użu tar-rota jevita emissjonijiet bla bżonn."},"CARS3.30":{"question_mt":"Biex tgħin lill-ambjent m'għandekx:","answers_mt":["Tneħħi piż mhux meħtieġ mill-bagoll","Tuża l-vettura għal vjaġġi qosra ħafna","Timxi, tuża rota jew trasport pubbliku","Tneħħi xtilliera fuq il-bejt vojt"],"explanation_mt":"Vjaġġi qosra ħafna b'magna kiesħa joħolqu tniġġis u konsum tal-fjuwil bla bżonn."},"CARS3.31":{"question_mt":"Xedd eċċessiv jew irregolari tat-tajers jista' jkun ikkawżat minn ħsarat f': Agħżel 3 tweġibiet.","answers_mt":["Is-sistema tal-egżost","Is-sospensjoni","L-aċċeleratur","Il-kaxxa tal-gerijiet","L-allinjament tar-roti","Is-sistema tal-brejkijiet"],"explanation_mt":"Ħsarat fis-sospensjoni, fl-allinjament tar-roti u fis-sistema tal-brejkijiet jistgħu jikkawżaw xedd irregolari tat-tajers."},"CARS3.33":{"question_mt":"Liema azzjonijiet inaqqsu l-konsum tal-fjuwil? Agħżel 2 tweġibiet.","answers_mt":["Tippjana sew minn qabel","Tnaqqas il-veloċità fit-triq","Taċċellera malajr","Tagħmel vjaġġi qosra b'magna kiesħa","Issuq f'gerijiet baxxi","Tibbrejkja tard u b'saħħa"],"explanation_mt":"Ippjanar tajjeb u veloċità aktar baxxa jgħinu għal sewqan bla skossi u effiċjenti."},"CARS3.45":{"question_mt":"F'xi toroq residenzjali ssib limitu ta' veloċità ta':","answers_mt":["80 km/h","60 km/h","35 km/h","50 km/h"],"explanation_mt":"Xi toroq residenzjali għandhom limitu ta' 35 km/h."},"CARS3.46":{"question_mt":"Ħotob fit-triq, kurvi artifiċjali għat-tnaqqis tal-veloċità u tidjiq tat-triq huma:","answers_mt":["Jinstabu biss fuq pontijiet bi ħlas","Jintużaw biex iżidu l-veloċità tat-traffiku","Dejjem jinstabu f'xogħlijiet kbar fit-triq","Miżuri biex inaqqsu l-veloċità tat-traffiku"],"explanation_mt":"Dawn il-karatteristiċi huma maħsuba biex inaqqsu l-veloċità tat-traffiku."},"CARS3.47":{"question_mt":"Tidħol fi triq fejn hemm ħotob fit-triq. Għandek:","answers_mt":["Iżżomm veloċità mnaqqsa tul iż-żona kollha","Issuq bil-mod biss fil-ħinijiet tal-iskola","Dejjem iżżomm il-veloċità massima legali","Taċċellera bejn ħotba u oħra"],"explanation_mt":"Żomm veloċità konsistentement mnaqqsa fiż-żona tat-tnaqqis tal-veloċità tat-traffiku."},"CARS4.5":{"question_mt":"Fi triq tajba u niexfa, bi brejkijiet u tajers tajbin, x'inhi d-distanza totali ta' waqfien b'48 km/h?","answers_mt":["96 metru","53 metru","36 metru","23 metru"],"explanation_mt":"Id-distanza totali ta' waqfien indikata b'48 km/h hija 23 metru."},"CARS4.6":{"question_mt":"Jekk tibbrejkja b'saħħa b'veloċità għolja f'liwja qawwija, il-vettura tiegħek tista' ssir:","answers_mt":["Iddur b'mod sigur","Instabbli","Tintefa l-magna","Aktar stabbli"],"explanation_mt":"Ibbrejkjar qawwi f'liwja jista' jfixkel il-bilanċ tal-vettura u jikkawża telf ta' kontroll."},"CARS4.10":{"question_mt":"Ir-regola taż-żewġ sekondi tippermettilek:","answers_mt":["Iżżomm distanza sigura mill-vettura ta' quddiem","Tiċċekkja l-mirja","Tiċċekkja l-angolu mejjet","Iżżomm id-distanza korretta mill-bankina"],"explanation_mt":"Hija regola sempliċi biex tkejjel distanza ta' sigurtà mill-vettura ta' quddiem."},"CARS4.11":{"question_mt":"Id-distanza totali ta' waqfien tkun itwal meta ssuq:","answers_mt":["Fix-xita","F'riħ qawwi","Bil-lejl","Fiċ-ċpar"],"explanation_mt":"Toroq imxarrba jnaqqsu l-qabda tat-tajers u jżidu d-distanza ta' waqfien."},"CARS4.16":{"question_mt":"X'inhi l-kawża ewlenija taż-żliq?","answers_mt":["It-triq","Is-sewwieq","Il-vettura","It-temp"],"explanation_mt":"Iż-żliq normalment ikun ikkawżat minn azzjonijiet tas-sewwieq bħal veloċità eċċessiva, istering jew ibbrejkjar."},"CARS4.21":{"question_mt":"F'temp sħun ħafna l-wiċċ tat-triq jista' jsir artab. Liema żewġ affarijiet jiġu affettwati l-aktar?","answers_mt":["Il-ħġieġa ta' quddiem","L-istering","Is-sospensjoni","L-ibbrejkjar"],"explanation_mt":"Wiċċ tat-triq artab jista' jnaqqas il-preċiżjoni tal-istering u l-qabda waqt l-ibbrejkjar."},"CARS4.22":{"question_mt":"L-indikaturi tiegħek jistgħu jkunu diffiċli biex jidhru f'xemx qawwija. X'għandek tagħmel?","answers_mt":["Iddur kemm jista' jkun malajr","Tagħti sinjal b'idejk minbarra li tuża l-indikatur","Tmiss il-brejkijiet diversi drabi","Tuża l-indikatur aktar kmieni"],"explanation_mt":"Sinjal bl-id jista' jsaħħaħ indikatur li jista' jkun diffiċli biex jidher."},"CARS4.25":{"question_mt":"Kif tista' tuża l-magna tal-vettura tiegħek bħala brejk?","answers_mt":["Tagħżel newtrali","Tibdel għal ger ogħla","Tagħżel marċ lura","Tibdel għal ger aktar baxx"],"explanation_mt":"Ger aktar baxx jipprovdi ibbrejkjar mill-magna."},"CARS4.27":{"question_mt":"Qed toqrob lejn ħotob fit-triq f'żona residenzjali. Għandek:","answers_mt":["Tieqaf u tiċċekkja ż-żewġ bankini","Tistenna lin-nies jaqsmu","Tnaqqas il-veloċità tal-vettura ħafna","Tersaq lejn in-naħa tax-xellug"],"explanation_mt":"Naqqas il-veloċità b'mod sinifikanti qabel ħotob fit-triq."},"CARS4.28":{"question_mt":"Meta toqrob lejn liwja lejn il-lemin, għaliex għandek iżżomm sew lejn ix-xellug?","answers_mt":["Biex tkun aktar sigur jekk il-vettura tiżloq","Biex tħalli lit-traffiku warajk jaqbżek","Biex tegħleb l-inklinazzjoni tat-triq","Biex ittejjeb il-veduta tiegħek tat-triq"],"explanation_mt":"Pożizzjoni lejn ix-xellug tagħtik veduta aħjar madwar liwja lejn il-lemin."},"CARS4.29":{"question_mt":"Qed toqrob lejn liwja lejn il-lemin. Għandek:","answers_mt":["Iżżomm lejn il-lemin biex il-liwja tkun inqas qawwija","Iżżomm lejn ix-xellug għal veduta aħjar","Iżżomm lejn il-lemin biex tevita l-kanal fil-ġenb tat-triq","Iżżomm lejn ix-xellug għax tagħmel il-liwja aktar mgħaġġla"],"explanation_mt":"Li żżomm lejn ix-xellug itejjeb il-veduta u s-sigurtà tiegħek fil-liwja."},"CARS5.3":{"question_mt":"Sewwieq jista' jaqra pjanċa tar-reġistrazzjoni mid-distanza meħtieġa biss bl-użu tan-nuċċalijiet. Meta għandhom jintlibsu n-nuċċalijiet?","answers_mt":["Il-ħin kollu waqt is-sewqan","Biss meta l-viżibbiltà tkun ħażina","Biss meta tagħmel marċ lura","Biss fi vjaġġi twal"],"explanation_mt":"Lentijiet korrettivi meħtieġa għandhom jintlibsu kull meta tkun qed issuq."},"CARS5.4":{"question_mt":"Ma tistax issib in-nuċċalijiet li għandek bżonn għas-sewqan. X'għandek tagħmel?","answers_mt":["Issuq lejn id-dar bil-lejl","Tissellef in-nuċċalijiet ta' ħabib","Issuq bil-mod fi toroq kwieti","Issib mod ieħor biex tmur id-dar mingħajr ma ssuq"],"explanation_mt":"Issuqx mingħajr il-lentijiet korrettivi li għandek bżonn."},"CARS5.5":{"question_mt":"Trid tilbes nuċċalijiet jew lentijiet tal-kuntatt waqt is-sewqan jekk:","answers_mt":["Hemm problema tal-vista fil-familja tiegħek","Ma tistax taqra pjanċa tar-reġistrazzjoni minn 36 metru","Għandek marka oranġjo","Ma tistax taqra pjanċa tar-reġistrazzjoni minn 20.5 metru mingħajrhom"],"explanation_mt":"Lentijiet korrettivi huma meħtieġa jekk mingħajrhom ma tissodisfax l-istandard tal-vista."},"CARS5.7":{"question_mt":"Liema tlieta huma effetti probabbli tax-xorb tal-alkoħol fuq is-sewqan?","answers_mt":["Ġudizzju ħażin","Żieda fil-kunfidenza","Daltoniżmu","Reazzjonijiet aktar mgħaġġla","Żieda fil-konċentrazzjoni","Koordinazzjoni mnaqqsa"],"explanation_mt":"L-alkoħol ixekkel il-ġudizzju u l-koordinazzjoni filwaqt li joħloq kunfidenza falza."},"CARS5.8":{"question_mt":"Ix-xorb ta' kwalunkwe ammont ta' alkoħol x'aktarx li: Agħżel 3 tweġibiet.","answers_mt":["Jagħtik sens falz ta' kunfidenza","Itejjeb l-għarfien tal-periklu","Iżid il-veloċità tar-reazzjoni","Jaggrava l-ġudizzju tal-veloċità","Inaqqas ir-reazzjoni għall-perikli"],"explanation_mt":"L-alkoħol joħloq kunfidenza falza, jaggrava l-ġudizzju u jnaqqas ir-reazzjonijiet."},"CARS5.9":{"question_mt":"Int mistieden għal ikla f'lokal u trid issuq filgħaxija. X'inhi l-aħjar għażla?","answers_mt":["Tiekol ikla sħuna flimkien mal-alkoħol","Tixrob ħalib qabel l-alkoħol","Tevita li tħallat xorb differenti","Ma tixrob l-ebda alkoħol"],"explanation_mt":"L-aktar għażla sigura meta trid issuq hija li ma tixrob l-ebda alkoħol."},"CARS5.11":{"question_mt":"Kif jaffettwa l-alkoħol is-sewqan tiegħek?","answers_mt":["Itejjeb il-koordinazzjoni","Iżid l-għarfien","Iħaffef ir-reazzjonijiet","Inaqqas il-konċentrazzjoni"],"explanation_mt":"L-alkoħol inaqqas il-konċentrazzjoni u l-kapaċità li ssuq b'mod sigur."},"CARS6.55":{"question_mt":"Rikkieb fuq żiemel jinsab fil-korsija tax-xellug u qed joqrob lejn rotonda. Is-sewwieq warajh għandu jistenna li r-rikkieb:","answers_mt":["Jibqa' sejjer dritt","Idur lejn ix-xellug","Idur lejn il-lemin","Jista' jmur fi kwalunkwe direzzjoni"],"explanation_mt":"Rikkieba taż-żwiemel jistgħu jieħdu pożizzjoni differenti għas-sigurtà, għalhekk tassumix id-direzzjoni tagħhom."},"CARS6.56":{"question_mt":"Qed toqrob lejn rotonda u hemm żwiemel ftit quddiemek. X'għandek tagħmel? Agħżel 2 tweġibiet.","answers_mt":["Iddoqq il-ħorn bħala twissija","Tagħtihom ħafna spazju","Taċċellera biex tgħaddihom malajr kemm jista' jkun","Tittrattahom bħal kull vettura oħra","Tkun lest li tieqaf"],"explanation_mt":"Agħti liż-żwiemel ħafna spazju u kun lest li tieqaf għax jistgħu jirreaġixxu b'mod imprevedibbli."},"CARS6.57":{"question_mt":"Tara grupp ta' rikkieba fuq iż-żwiemel joqorbu lejn rotonda. Qed jagħtu sinjal lejn il-lemin iżda qed iżommu sew lejn ix-xellug. X'għandek tagħmel?","answers_mt":["Tidħol quddiemhom","Tibqa' qrib tagħhom","Tkompli bħas-soltu","Tibqa' sew lura"],"explanation_mt":"Rikkieba taż-żwiemel jistgħu jkollhom bżonn spazju żejjed biex iduru b'mod sigur, għalhekk ibqa' sew lura."},"CARS6.58":{"question_mt":"X'inhi l-aktar kawża komuni ta' inċidenti tat-traffiku?","answers_mt":["Ħsara mekkanika","Żball tas-sewwieq","Kundizzjonijiet tat-triq","Kundizzjonijiet tat-temp"],"explanation_mt":"Żball tas-sewwieq huwa l-aktar kawża komuni ta' inċidenti tat-traffiku."},"CARS6.60":{"question_mt":"Liema grupp ta' età huwa l-aktar probabbli li jkun involut f'inċidenti tat-traffiku?","answers_mt":["46 sa 55 sena","55 sena u aktar","36 sa 45 sena","18 sa 25 sena"],"explanation_mt":"Statistikament, sewwieqa żgħażagħ bejn 18 u 25 sena huma aktar probabbli li jkunu involuti f'inċidenti tat-traffiku."},"CARS6.61":{"question_mt":"Qed issegwi sewwieq apprendist li l-magna tiegħu tintefa f'salib it-toroq. X'għandek tagħmel?","answers_mt":["Kun paċenzjuż għax apprendisti jistgħu jagħmlu żbalji","Tdur minnufih madwaru u tkompli","Tgħolli r-revs tal-magna jekk idum wisq","Tersaq qrib warajh u tixgħel u titfi l-fanali ta’ quddiem"],"explanation_mt":"Kun paċenzjuż u tagħmilx pressjoni fuq sewwieq mingħajr esperjenza."},"CARS7.4":{"question_mt":"Qed tistenna biex toħroġ lejn ix-xellug minn triq sekondarja. Vettura kbira qed toqrob mil-lemin. Għandek ħin iddur, iżda xorta għandek tistenna. Għaliex?","answers_mt":["Tista' taħbi vetturi mix-xellug","Hija diffiċli biex iżżommha dritta","Tista' ddur f'daqqa","Tista' taħbi vettura li qed taqbiżha"],"explanation_mt":"Vettura kbira tista' taħbi vettura oħra li tkun qed taqbiżha."},"CARS9.7":{"question_mt":"Għal xiex għandek tuża l-korsija ta’ emerġenza ta' karreġġjata b’diversi korsiji?","answers_mt":["Biex tieqaf f'emerġenza","Biex tidħol fil-karreġġjata","Biex tieqaf meta tkun għajjien","Biex toħroġ mill-karreġġjata"],"explanation_mt":"Il-korsija ta’ emerġenza hija għall-emerġenzi biss."},"CARS9.8":{"question_mt":"Wara ħsara, kif għandek terġa' tidħol f'karreġġjata b’diversi korsiji mill-korsija ta’ emerġenza?","answers_mt":["Tistenna sakemm xi ħadd jagħtik teptip tal-fanali ta’ quddiem","Toħroġ waqt li tuża d-dwal ta’ emerġenza","Tibni l-veloċità fuq il-korsija ta’ emerġenza qabel toħroġ","Toħroġ l-ewwel u mbagħad taċċellera"],"explanation_mt":"Ibni l-veloċità fuq il-korsija ta’ emerġenza qabel tingħaqad mat-traffiku meta jkun sigur."},"CARS9.9":{"question_mt":"L-intervall minimu ta' ħin sigur f'kundizzjonijiet tajbin huwa mill-inqas:","answers_mt":["Tliet sekondi","Sekonda waħda","Erba' sekondi","Żewġ sekondi"],"explanation_mt":"F'kundizzjonijiet tajbin, żomm distanza ta' mill-inqas żewġ sekondi."},"CARS9.10":{"question_mt":"Biħsiebek toħroġ minn karreġġjata b’diversi korsiji fil-ħruġ li jmiss. Fejn normalment għandek tqiegħed il-vettura?","answers_mt":["Fi kwalunkwe korsija","Fil-korsija tax-xellug","Fuq il-korsija ta’ emerġenza","Fil-korsija tan-nofs"],"explanation_mt":"Mur fil-korsija tax-xellug minn kmieni qabel il-ħruġ tiegħek."},"CARS9.11":{"question_mt":"Tgħaddi l-ħruġ li ridt fuq karreġġjata b’diversi korsiji. X'għandek tagħmel?","answers_mt":["Tagħmel dawra f’forma ta’ U fl-ewwel fetħa","Tkompli sal-ħruġ li jmiss","Tagħmel marċ lura fil-korsija tax-xellug","Tagħmel marċ lura fuq il-korsija ta’ emerġenza"],"explanation_mt":"Qatt tagħmel marċ lura jew iddur lura; kompli sal-ħruġ li jmiss."},"CARS10.1":{"question_mt":"Meta tista' ssuq minn fuq bankina?","answers_mt":["Jekk ma jkun hemm l-ebda persuna miexja viċin","Meta jkun wiesa' ħafna","Biex taqbeż traffiku miexi bil-mod","Biex tikseb aċċess legali għal proprjetà"],"explanation_mt":"Tista' taqsam bankina biss biex tikseb aċċess legali għal proprjetà."},"CARS10.3":{"question_mt":"X'inhu l-limitu nazzjonali tal-veloċità barra ż-żoni mibnija għall-karozzi u l-muturi, sakemm ma jkunx indikat mod ieħor?","answers_mt":["100 km/h","60 km/h","80 km/h","50 km/h"],"explanation_mt":"Il-limitu nazzjonali barra ż-żoni mibnija huwa 80 km/h, sakemm is-sinjali ma jgħidux mod ieħor."},"CARS10.6":{"question_mt":"Xi jfisser sinjal ta' limitu massimu tal-veloċità?","answers_mt":["Il-veloċità hija sigura f'kull kundizzjoni","Il-veloċità hija biss rakkomandata","Il-veloċità tista' tinqabeż meta t-triq tkun vojta","M'għandekx taqbeż il-veloċità murija"],"explanation_mt":"In-numru muri huwa l-massimu legali, mhux mira li trid tilħaq."},"CARS12.8":{"question_mt":"Liema żewġ tipi ta' informazzjoni jinsabu fid-dokument ta' reġistrazzjoni ta' vettura?","answers_mt":["Il-marka tal-vettura","Is-sid irreġistrat","It-tip ta' kopertura tal-assigurazzjoni","Id-data tal-VRT","L-istorja tas-servizz"],"explanation_mt":"Id-dokument ta' reġistrazzjoni jirreġistra l-marka tal-vettura u s-sid irreġistrat."},"CARS12.11":{"question_mt":"Min huwa responsabbli biex jiżgura li vettura tkun kompletament tajba u sigura għat-triq meta tinstaq fi triq pubblika?","answers_mt":["Ħadd b'mod partikolari","Il-mekkanik tiegħek","L-eżaminatur tal-VRT","Int, is-sewwieq"],"explanation_mt":"Is-sewwieq huwa responsabbli biex il-vettura tkun tajba u sigura għat-triq meta tintuża fit-triq."},"CARS13.1":{"question_mt":"Fuq il-post ta' inċident għandek:","answers_mt":["Ma tqiegħedx lilek innifsek f'riskju","Tħalli l-magni mixgħula","Toħroġ lil kulħadd mill-vetturi","Tmur l-ewwel għand dawk li qed jgħajtu"],"explanation_mt":"L-ewwel prijorità tiegħek hija li tevita li ssir vittma oħra."},"CARS13.2":{"question_mt":"Int l-ewwel li tasal fuq inċident. Liema erba' azzjonijiet għandek tieħu?","answers_mt":["Twissi traffiku ieħor","Iċċempel lis-servizzi tal-emerġenza","Tbiegħed lin-nies mhux imweġġgħin","Titfi l-magni tal-vetturi","Titlaq meta jasal sewwieq ieħor","Tagħti x'tixrob lill-vittmi"],"explanation_mt":"Assigura l-post, ċempel għall-għajnuna, biegħed lin-nies mhux imweġġgħin u itfi l-magni."},"CARS13.3":{"question_mt":"Int l-ewwel fuq inċident fejn hemm nies imweġġgħin serjament. Liema tliet azzjonijiet għandek tieħu?","answers_mt":["Toħroġ lin-nies imweġġgħin mill-vetturi","Tagħti x'tixrob lin-nies imweġġgħin","Tbiegħed lin-nies mhux imweġġgħin","Tiżgura li xi ħadd iċempel ambulanza","Tixgħel id-dwal ta’ emerġenza tiegħek"],"explanation_mt":"Ipproteġi l-post, ċempel ambulanza u biegħed biss lin-nies mhux imweġġgħin."},"LPTV2026.001":{"question_mt":"Mit-29 ta' Lulju 2026, għal kemm żmien irid applikant ikun ilu għandu liċenzja tas-sewqan valida tal-UE Kategorija B qabel japplika għal LPTV Tag tal-Permess tas-Sewwieq?","answers_mt":["Mill-inqas 6 xhur","Mill-inqas sena","Mill-inqas sentejn","Mill-inqas 5 snin"],"explanation_mt":"Ir-rekwiżit il-ġdid ta' eliġibbiltà huwa li tkun ilek mill-inqas sentejn b'liċenzja tas-sewqan valida tal-UE Kategorija B."},"LPTV2026.002":{"question_mt":"Meta tapplika għal Tag tal-Permess tas-Sewwieq LPTV, x’inhu n-numru massimu ta’ punti ta’ penali permess?","answers_mt":["3 punti","6 punti","9 punti","12-il punt"],"explanation_mt":"L-applikant ma jistax ikollu aktar minn sitt punti ta’ penali."},"LPTV2026.003":{"question_mt":"Kemm-il passiġġier, minbarra s-sewwieq, tista’ ġġorr vettura ħafifa għat-trasport tal-passiġġieri?","answers_mt":["Sa 6","Sa 7","Sa 8","Sa 9"],"explanation_mt":"LPTV jista' jġorr sa tmien passiġġieri minbarra s-sewwieq."},"LPTV2026.004":{"question_mt":"Meta vettura bi pjanċa Y tkun ipparkjata fit-triq u ma tkunx qed tintuża, x'għandu jkun espost b'mod ċar?","answers_mt":["Nota miktuba bl-idejn","L-arloġġ uffiċjali tal-parkeġġ ta' Transport Malta","Kopja taċ-ċertifikat tal-assigurazzjoni","Il-karta tal-identità tas-sewwieq"],"explanation_mt":"L-arloġġ uffiċjali tal-parkeġġ ta' Transport Malta għandu jkun espost u ssettjat b'mod korrett."},"LPTV2026.005":{"question_mt":"Għal kemm żmien tista' vettura bi pjanċa Y tibqa' pparkjata fit-triq bejn il-05:01 u l-16:59?","answers_mt":["30 minuta","Siegħa","Sagħtejn","3 sigħat"],"explanation_mt":"Il-limitu ta' parkeġġ fit-triq matul il-jum huwa sagħtejn."},"LPTV2026.006":{"question_mt":"Għal kemm żmien tista' vettura bi pjanċa Y tibqa' pparkjata fit-triq bejn is-17:00 u l-05:00?","answers_mt":["30 minuta","Siegħa","Sagħtejn","3 sigħat"],"explanation_mt":"Il-limitu ta' parkeġġ fit-triq matul il-lejl huwa siegħa."},"LPTV2026.007":{"question_mt":"Liema penali amministrattiva tista' tapplika jekk ma tesponix jew ma tużax b'mod korrett l-arloġġ uffiċjali tal-parkeġġ ta' Transport Malta?","answers_mt":["€50","€100","€250","€500"],"explanation_mt":"Jekk l-arloġġ uffiċjali tal-parkeġġ ma jintweriex jew ma jintużax b'mod korrett tista' tiġi imposta penali ta' €500."},"LPTV2026.009":{"question_mt":"X'inhu l-ħin massimu li sewwieq LPTV jista' jaħdem fi kwalunkwe perjodu ta' 24 siegħa?","answers_mt":["8 sigħat","10 sigħat","12-il siegħa","14-il siegħa"],"explanation_mt":"Sewwieq m'għandux jaħdem aktar minn tnax-il siegħa fi kwalunkwe perjodu ta' erbgħa u għoxrin siegħa."},"LPTV2026.010":{"question_mt":"X'mistrieħ fil-ġimgħa għandu jkollu sewwieq LPTV?","answers_mt":["Mill-inqas nofs ta' nhar","Mill-inqas ġurnata","Mill-inqas jumejn","M'hemmx mistrieħ fiss fil-ġimgħa"],"explanation_mt":"Is-sewwieqa għandhom ikollhom mill-inqas ġurnata waħda ta' mistrieħ kull ġimgħa."},"LPTV2026.011":{"question_mt":"Liema teknoloġija għandhom jużaw pjattaformi intermedjarji tal-prenotazzjoni biex jivverifikaw l-identità ta' sewwieq?","answers_mt":["Qari tal-marki tas-swaba’ biss","Teknoloġija ta' rikonoxximent tal-wiċċ","Firma miktuba bl-idejn","GPS tal-vettura biss"],"explanation_mt":"Il-pjattaformi għandhom jużaw rikonoxximent tal-wiċċ biex jivverifikaw li s-sewwieq awtorizzat qed juża l-kont."},"LPTV2026.012":{"question_mt":"Jista' sewwieq LPTV iħalli persuna oħra tuża l-kont tas-sewwieq tiegħu jew tagħha biex tipprovdi servizzi ta' trasport tal-passiġġieri?","answers_mt":["Iva, jekk il-persuna l-oħra għandha esperjenza","Iva, sa siegħa","Le","Biss bil-permess tal-passiġġier"],"explanation_mt":"Sewwieq m'għandux iħalli persuna oħra tuża l-kont jew il-profil tiegħu jew tagħha."},"SCHOOL.001":{"question_mt":"Meta tkun qed tgħin lil xi ħadd li jinsab f’xokk, x’għandek tagħmel? Agħżel 2 tweġibiet.","answers_mt":["Serrħilu moħħu","Ħoll ħwejjeġ issikkati","Agħtih alkoħol","Ġiegħlu jimxi"],"explanation_mt":"Persuna f’xokk għandha tiġi serħan il-moħħ u għandhom jinħallu ħwejjeġ issikkati. Tagħtihiex alkoħol u ġġegħilhiex timxi."},"SCHOOL.002":{"question_mt":"F'inċident, meta ż-żona tkun sigura, x'għandek tagħmel l-ewwel għal persuna midruba li għadha ġewwa vettura perikoluża?","answers_mt":["Toħroġha biss jekk hemm periklu immedjat","Tagħtiha l-ilma","Titlobha tqum bilwieqfa","Titlaq mingħajr ma ċċempel għall-għajnuna"],"explanation_mt":"Normalment persuni midruba m'għandhomx jiġu mċaqalqa, ħlief jekk hemm periklu immedjat bħal nar."},"SCHOOL.003":{"question_mt":"Waqt is-sewqan, l-istering f'daqqa jsir tqil. X'jista' jindika dan? Agħżel 2 tweġibiet.","answers_mt":["Titqib f’tajar ta’ quddiem","Ħsara fl-istering assistit","Livell baxx tal-likwidu tal-wajpers","Ċinturin tas-sigurtà maħlul"],"explanation_mt":"Istering tqil jista’ jkun ikkawżat minn titqib f’tajar ta’ quddiem jew ħsara fl-istering assistit."},"SCHOOL.004":{"question_mt":"X'għandek tiċċekkja l-ewwel qabel timxi lejn il-lemin?","answers_mt":["Il-mera tas-sewwieq fuq in-naħa ta' barra","Il-mera tan-naħa tal-bankina biss","Is-sedil ta' wara","L-indikatur tal-fjuwil"],"explanation_mt":"Qabel timxi lejn il-lemin, l-ewwel iċċekkja l-mera ta' barra fuq in-naħa tas-sewwieq."},"SCHOOL.005":{"question_mt":"Biex tipprevjeni t-tixrid tal-fjuwil, huwa importanti li:","answers_mt":["Tagħlaq u tissikka sew it-tappijiet tal-mili kollha","Timla l-ġibjun tal-fjuwil iżżejjed","Tħalli l-għatu tal-fjuwil miftuħ","Timla l-fjuwil bil-magna mixgħula"],"explanation_mt":"It-tappijiet tal-mili kollha għandhom ikunu magħluqa u ssikkati sew."},"SCHOOL.006":{"question_mt":"Il-vetturi għamlu ħsara lill-ambjent. X'irriżulta minn dan? Agħżel 3 tweġibiet.","answers_mt":["Tniġġis tal-arja","Ħsara lill-bini","Konsum tar-riżorsi naturali","Arja aktar nadifa","Inqas konsum tal-fjuwil"],"explanation_mt":"It-trasport bit-triq jikkontribwixxi għat-tniġġis tal-arja, għall-ħsara lill-bini u għat-tnaqqis tar-riżorsi naturali."},"SCHOOL.007":{"question_mt":"Trid iddur lejn il-lemin f'salib it-toroq immarkat b'żewġ korsiji għad-dawra lejn il-lemin. Hemm spazju biżżejjed fiż-żewġ korsiji. X'għandek tagħmel?","answers_mt":["Tuża l-korsija tal-lemin, imbagħad timxi lejn ix-xellug hekk kif tidħol fit-triq il-ġdida","Tuża l-korsija tax-xellug u taqsam quddiem l-oħra","Tieqaf fiż-żewġ korsiji","Tibdel korsija mingħajr ma tiċċekkja"],"explanation_mt":"Uża l-korsija tal-lemin u segwi l-marki tat-triq biex tidħol fil-korsija korretta wara d-dawra."},"SCHOOL.008":{"question_mt":"Għaliex iż-żejt tal-magna għandu jinbidel fl-intervalli rakkomandati?","answers_mt":["Biex inaqqas il-frizzjoni u x-xedd","Biex iżid id-duħħan tal-egżost","Biex jagħmel il-brejkijiet aktar iebsin","Biex inaqqas il-pressjoni tat-tajers"],"explanation_mt":"Żejt frisk tal-magna jillubrika l-partijiet li jiċċaqalqu u jnaqqas il-frizzjoni u x-xedd."},"SCHOOL.009":{"question_mt":"Tista' tneħħi s-ċinturin tas-sigurtà meta tkun qed tagħmel manuvra li tinvolvi:","answers_mt":["Marċ lura","Sorpass","Sewqan minn mina","Meta toqrob lejn salib it-toroq"],"explanation_mt":"L-eżenzjoni tapplika meta tagħmel marċ lura jekk iċ-ċinturin tas-sigurtà jirrestrinġi l-manuvra."},"SCHOOL.010":{"question_mt":"F'xita qawwija, mill-inqas kemm għandha tkun id-distanza tal-ibbrejkjar meta mqabbla man-normal?","answers_mt":["L-istess distanza","Darbtejn id-distanza normali","Nofs id-distanza normali","Tliet darbiet id-distanza normali f'kull każ"],"explanation_mt":"F'kundizzjonijiet imxarrba għandek tħalli mill-inqas darbtejn id-distanza normali."},"SCHOOL.011":{"question_mt":"X'għandek tagħmel meta tibbrejkja b'saħħa f'vettura mgħammra b'ABS?","answers_mt":["Tagħfas il-brejk b'saħħa u kontinwament","Tippompja l-pedala tal-brejk","Tuża biss il-brejk tal-parkeġġ","Tneħħi kompletament il-brejk"],"explanation_mt":"B'ABS, applika pressjoni soda u kontinwa. L-ippumpjar tal-pedala jista' jnaqqas l-effettività."},"SCHOOL.012":{"question_mt":"F'vettura mingħajr ABS, x'jgħin l-aktar biex ir-roti ma jissakkrux waqt ibbrejkjar ta' emerġenza?","answers_mt":["Tuża ibbrejkjar ikkontrollat qrib il-punt fejn ir-roti jissakkru","Tapplika l-brejk tal-parkeġġ kompletament","Titfi l-magna","Tippompja l-aċċeleratur"],"explanation_mt":"Ibbrejkjar ikkontrollat qrib il-punt fejn ir-roti jissakkru jgħin biex jinżamm il-kontroll tal-istering."},"SCHOOL.013":{"question_mt":"Karozza tal-Pulizija qed issegwik u l-uffiċjali jridu li tieqaf. Kif jistgħu jagħtuk is-sinjal?","answers_mt":["Billi jixegħlu u jitfu l-fanali ta’ quddiem u jattivaw id-dwal blu jew sinjali ċari oħra tal-Pulizija","Billi jdoqqu l-ħorn biss","Billi jaqbżuk mingħajr sinjal","Billi jitfu d-dwal kollha"],"explanation_mt":"Obdi struzzjonijiet ċari tal-Pulizija u ieqaf b'mod sigur malajr kemm jista' jkun."},"SCHOOL.014":{"question_mt":"Kundanna għal sewqan meta ma tkunx tajjeb biex issuq minħabba xorb jew drogi x'aktarx iżżid l-ispiża ta':","answers_mt":["L-assigurazzjoni tal-vettura","It-tiġdid tal-liċenzja tas-sewqan","Il-fjuwil","L-eżami VRT"],"explanation_mt":"Kundanni bħal dawn normalment iwasslu għal primjums tal-assigurazzjoni tal-vettura ħafna ogħla."},"SCHOOL.015":{"question_mt":"Qatt m'għandek tipprova taqbeż ċiklist:","answers_mt":["F'rotonda","Fi triq dritta b'ħafna spazju","B'veloċità baxxa u b'distanza wiesgħa","Meta t-triq quddiemek tkun kompletament vojta"],"explanation_mt":"Taqbiżx ċiklisti f'rotonda għax il-linja u d-direzzjoni tagħhom jistgħu jinbidlu."},"SCHOOL.016":{"question_mt":"Biħsiebek iddur lejn il-lemin għal triq sekondarja. Eżatt qabel iddur, għandek tiċċekkja għal sewwieqa tal-muturi li jistgħu jkunu:","answers_mt":["Qed jaqbżuk min-naħa tal-lemin","Ipparkjati fuq il-bankina","Qed isegwu 'l bogħod warajk","Qed iduru lejn ix-xellug warajk"],"explanation_mt":"Sewwieq tal-mutur jista' jkun qed jaqbżek min-naħa tal-lemin u jkun moħbi fil-angolu mejjet tiegħek."},"SCHOOL.017":{"question_mt":"Fi triq tal-kampanja, x'tista' tistenna li tara ġej lejk fuq in-naħa tiegħek tat-triq?","answers_mt":["Rikkieba fuq iż-żwiemel","Karozzi pparkjati biss","Dwal tat-traffiku","Ostakli għall-persuni mexjin"],"explanation_mt":"Rikkieba fuq iż-żwiemel jistgħu jużaw it-triq u jistgħu jkunu 'l bogħod mit-tarf għas-sigurtà."},"SCHOOL.018":{"question_mt":"L-użu ta' telefon bla idejn waqt is-sewqan x'aktarx li:","answers_mt":["Jtelliflek l-attenzjoni","Itejjeb il-konċentrazzjoni","Iqassar id-distanza ta' waqfien","Jagħmel l-istering eħfef"],"explanation_mt":"Telefonati bla idejn xorta joħolqu distrazzjoni mentali."},"SCHOOL.019":{"question_mt":"Għaliex għandek tħalli spazju żejjed lis-sewwieqa tal-muturi li jkunu għaddejjin minn xogħlijiet fit-triq?","answers_mt":["Jistgħu jiddevjaw biex jevitaw ħofor fit-triq","Dejjem isuqu aktar malajr","Ma jistgħux jużaw il-brejkijiet","Iridu jsuqu fin-nofs"],"explanation_mt":"Is-sewwieqa tal-muturi jistgħu jkollhom bżonn jibdlu d-direzzjoni f'daqqa biex jevitaw ħofor fit-triq jew wiċċ maħlul."},"SCHOOL.020":{"question_mt":"Qed issuq vettura b'duħħan eċċessiv mill-egżost. Liema dikjarazzjoni hija korretta?","answers_mt":["Jista' jkun li qed tikser il-liġi","Huwa aċċettabbli fi vjaġġi qosra","Jaffettwa biss l-ekonomija tal-fjuwil","Huwa sigur jekk il-magna tkun sħuna"],"explanation_mt":"Duħħan eċċessiv mill-egżost jista' jindika difett u jista' jkun reat."},"CUSTOMER.001":{"question_mt":"Passiġġier jirrifjuta li jħallas in-noll miftiehem. X'għandek tagħmel l-ewwel?","answers_mt":["Tibqa' kalm u ssegwi l-proċedura tal-operatur","Tillokkja lill-passiġġier fil-vettura","Tuża forza fiżika","Titlaq bil-bagalji tal-passiġġier"],"explanation_mt":"Ibqa' professjonali, evita konfrontazzjoni u segwi l-proċedura tal-operatur jew dik tar-rappurtar lill-Pulizija."},"CUSTOMER.002":{"question_mt":"Familja titolbok taqbeż il-limitu tal-veloċità għax waslet tard għall-ajruport. X'għandek tagħmel?","answers_mt":["Tobdi l-limitu tal-veloċità u ssuq b'mod sigur","Taqbeż il-limitu biss fi toroq vojta","Titlob ħlas żejjed u taċċellera","Tuża dwal ta’ emerġenza u taqbeż il-limitu"],"explanation_mt":"L-urġenza tal-passiġġier qatt ma tiġġustifika li tikser il-limitu tal-veloċità."},"CUSTOMER.003":{"question_mt":"Meta ġġorr passiġġier vulnerabbli, x'għandek tagħmel? Agħżel 2 tweġibiet.","answers_mt":["Issuq bla skossi","Toffri assistenza xierqa","Tibbrejkja b'saħħa biex tiffranka l-ħin","Tiddiskuti l-kundizzjoni tal-passiġġier ma' persuni barranin"],"explanation_mt":"Ipprovdi vjaġġ bla skossi u assistenza xierqa filwaqt li tirrispetta d-dinjità u l-privatezza."},"CUSTOMER.004":{"question_mt":"Passiġġier b'diżabilità jgħid li m'għandux bżonn għajnuna. X'għandek tagħmel?","answers_mt":["Tirrispetta d-deċiżjoni tiegħu iżda tibqa' lest biex tgħin","Tinsisti li tgħinu fiżikament","Tirrifjuta l-vjaġġ","Tinjoraw kull talba futura"],"explanation_mt":"Irrispetta l-indipendenza tal-passiġġier filwaqt li tibqa' disponibbli jekk aktar tard jitlob l-għajnuna."},"CUSTOMER.005":{"question_mt":"Għas-sigurtà u l-kumdità tal-passiġġieri, liema azzjonijiet huma xierqa? Agħżel 3 tweġibiet.","answers_mt":["Tibbrejkja bla skossi","Taħseb sew minn qabel","Tieqaf qrib il-bankina fejn ikun sigur","Tagħti l-bqija waqt li l-vettura tkun miexja","Taċċellera f'daqqa"],"explanation_mt":"Sewqan bla skossi, antiċipazzjoni u waqfien sigur qrib il-bankina jtejbu s-sigurtà u l-kumdità tal-passiġġieri."},"CARS13.4":{"question_mt":"Tasal fuq il-post ta' inċident ta' mutur u r-rikkieb ikun imweġġa'. Meta għandu jitneħħa l-elmu?","answers_mt":["Biss meta jkun essenzjali","Dejjem sakemm ir-rikkieb ma jkunx fi xokk","Biss meta s-sewwieq tal-mutur jitlob","Dejjem minnufih"],"explanation_mt":"Elmu ta' mutur għandu jitneħħa biss meta jkun essenzjali, pereżempju biex tinżamm passaġġ tal-arja miftuħ."},"CARS13.5":{"question_mt":"Tasal fuq il-post ta' inċident serju ta' mutur. Is-sewwieq tal-mutur huwa mitluf minn sensih u qed joħroġlu d-demm. X'inhuma l-prijoritajiet ewlenin tiegħek? Agħżel 3 tweġibiet.","answers_mt":["Tiċċekkja n-nifs tal-persuna","Tipprova twaqqaf kwalunkwe fsada","Tiġbor fdalijiet maħlula","Tniżżel in-numri tar-reġistrazzjoni tal-vetturi","Tiċċekkja li l-passaġġ tan-nifs huwa miftuħ","Tagħmel lista tax-xhieda"],"explanation_mt":"Il-prijoritajiet immedjati huma li tiżgura li l-passaġġ tan-nifs ikun miftuħ, tivverifika n-nifs u twaqqaf fsada severa."},"CARS13.6":{"question_mt":"Tasal fuq inċident. Sewwieq tal-mutur huwa mitluf minn sensih. X'inhi l-ewwel prijorità tiegħek?","answers_mt":["In-nifs","Tbenġil","Għadam miksur","Fsada"],"explanation_mt":"In-nifs għandu jiġi ċċekkjat minnufih."},"CARS13.7":{"question_mt":"F'inċident persuna midruba hija mitlufa minn sensiha. Liema tliet affarijiet għandek tiċċekkja b'urġenza?","answers_mt":["Għadam miksur","Passaġġ tan-nifs","Xokk","Ċirkolazzjoni","Nifs"],"explanation_mt":"Il-kontrolli urġenti jsegwu l-prinċipju ABC: passaġġ tan-nifs, nifs u ċirkolazzjoni."},"CARS13.8":{"question_mt":"Fil-l-ewwel għajnuna, xi tfisser ABC? Agħżel 3 tweġibiet.","answers_mt":["Ċirkolazzjoni","Passaġġ tan-nifs","Fsada","Konxju","Nifs","F’sensih"],"explanation_mt":"ABC tfisser passaġġ tan-nifs, nifs u ċirkolazzjoni."},"CARS13.9":{"question_mt":"F'inċident xi ħadd huwa mitluf minn sensih. X'inhuma l-prijoritajiet ewlenin tiegħek? Agħżel 3 tweġibiet.","answers_mt":["Tiżgura li qed jieħu n-nifs","Tiċċekkja li l-passaġġ tan-nifs huwa miftuħ","Twaqqaf kwalunkwe fsada qawwija","Tgħodd il-vetturi involuti","Tieħu l-ismijiet tax-xhieda","Tiġbor il-ħġieġ miksur"],"explanation_mt":"Il-passaġġ tan-nifs, in-nifs u fsada severa jieħdu prijorità."},"CARS13.11":{"question_mt":"Seħħ inċident u s-sewwieq jinsab fi xokk. X'għandek tagħmel? Agħżel 2 tweġibiet.","answers_mt":["Ma tħallix lis-sewwieq waħdu","Serrħilu moħħu","Tistaqsih min ikkawża l-inċident","Toffrilu sigarett","Tagħtih x'jixrob"],"explanation_mt":"Ibqa' mal-persuna midruba u serrħilha moħħha."},"CARS6.19":{"question_mt":"Jekk qed issegwi karozza misjuqa minn sewwieq anzjan, x'għandek tiftakar?","answers_mt":["Tibqa' qrib ħafna warajh","Tixgħel u titfi d-dwal u taqbżu","Ir-reazzjonijiet tas-sewwieq jistgħu ma jkunux veloċi daqs tiegħek","Tistenna li s-sewwieq isuq ħażin"],"explanation_mt":"Ħalli aktar ħin u spazju għax ir-reazzjonijiet jistgħu jkunu aktar bil-mod."},"CARS6.22":{"question_mt":"Jekk tara persuna miexja ġġorr bastun abjad, x'jindika dan?","answers_mt":["Il-persuna hija anzjana","Il-persuna hija nieqsa mis-smigħ","Il-persuna għandha diżabilità","Il-persuna hija għamja"],"explanation_mt":"Bastun abjad jindika li l-persuna miexja hija għamja."},"CARS6.23":{"question_mt":"Qed issuq lejn qsim taż-żebra. Persuna f'siġġu tar-roti qed tistenna biex taqsam. X'għandek tagħmel?","answers_mt":["Tagħmel sinjal lill-persuna biex tistenna","Tagħmel sinjal lill-persuna biex taqsam","Tkompli fi triqtek","Tkun lest li tieqaf"],"explanation_mt":"Avviċina b'attenzjoni u kun lest li tieqaf."},"CARS6.24":{"question_mt":"X'għandek tagħmel meta persuni anzjani jkunu qed jaqsmu t-triq?","answers_mt":["Tmiss il-ħorn","Tkun paċenzjuż u tħallihom jaqsmu bil-pass tagħhom","Tgħolli r-revs tal-magna","Tagħmlilhom sinjal biex jaqsmu"],"explanation_mt":"Kun paċenzjuż u tagħmilx pressjoni fuq nies vulnerabbli li jkunu qed jaqsmu."},"CARS6.27":{"question_mt":"Qatt m'għandek tipprova taqbeż ċiklist:","answers_mt":["Eżatt qabel iddur lejn ix-xellug","F'karreġġjata doppja","Fi triq b’direzzjoni waħda","Eżatt qabel iddur lejn il-lemin"],"explanation_mt":"Meta taqbeż ċiklist qabel dawra lejn ix-xellug hemm riskju li taqsamlu triqtu."},"CARS6.28":{"question_mt":"Qed issuq wara ċiklist u biħsiebek iddur lejn ix-xellug ftit 'il quddiem. X'għandek tagħmel?","answers_mt":["Tgħaddi madwar iċ-ċiklist fis-salib it-toroq","Tersaq maġenbu u tibqa' fl-istess livell","Tibqa' warajh sakemm iċ-ċiklist ikun għadda s-salib it-toroq","Taqbżu qabel is-salib it-toroq"],"explanation_mt":"Taqsamx it-triq taċ-ċiklist; stenna warajh."},"CARS6.29":{"question_mt":"Qed toqrob lejn rotonda u ċiklist qed jagħti sinjal lejn il-lemin. X'għandek tagħmel?","answers_mt":["Tagħti sinjal liċ-ċiklist biex jaqsam","Iddoqq il-ħorn","Taqbżu min-naħa tal-lemin","Tagħti liċ-ċiklist ħafna spazju"],"explanation_mt":"Iċ-ċiklisti għandhom bżonn spazju żejjed u jistgħu jibdlu l-pożizzjoni tagħhom għas-sigurtà."},"CARS6.30":{"question_mt":"Tliet ċiklisti qed joqorbu lejn rotonda fil-korsija tax-xellug. F'liema direzzjoni għandek tistenna li jmorru?","answers_mt":["Dritt 'il quddiem","Lejn il-lemin","Fi kwalunkwe direzzjoni","Lejn ix-xellug"],"explanation_mt":"Iċ-ċiklisti jistgħu jibqgħu fuq ix-xellug għas-sigurtà anke meta jkunu se jieħdu ħruġ ieħor."},"CARS10.5":{"question_mt":"Tara quddiemek sinjal ta' limitu massimu ta' 30 km/h. Xi jfisser?","answers_mt":["Il-veloċità minima hija 30 km/h","Qed toħroġ minn żona ta' 30 km/h","Naqqas għal 30 km/h biss wara li tgħaddi s-sinjal","Taqbiżx 30 km/h wara li tgħaddi s-sinjal"],"explanation_mt":"Il-limitu japplika minn fejn jinsab is-sinjal 'il quddiem."},"CARS11.7":{"question_mt":"Xi jfisser is-sinjal ta' tmiem żona ta' 20 km/h?","answers_mt":["Veloċità minima ta' 30 km/h","L-ebda vettura ta’ aktar minn 30 tunnellata","Limitu ġdid ta' veloċità ta' 20 km/h","Tmiem iż-żona ta' 20 km/h"],"explanation_mt":"Is-sinjal jimmarka t-tmiem taż-żona ta' 20 km/h."},"CARS11.8":{"question_mt":"Xi jfisser is-sinjal 'vetturi bil-mutur ipprojbiti'?","answers_mt":["L-ebda vettura bil-mutur","Karozzi u muturi biss","Triq fejn il-waqfien huwa pprojbit","Ebda qbiż"],"explanation_mt":"Vetturi bil-mutur huma pprojbiti lil hinn mis-sinjal."},"CARS11.9":{"question_mt":"Xi jfisser sinjal 'dħul ipprojbit'?","answers_mt":["Triq mingħajr ħruġ","L-ebda marki tal-karreġġjata","Ebda parkeġġ","Dħul ipprojbit"],"explanation_mt":"Il-vetturi m'għandhomx jidħlu minn dik id-direzzjoni."},"CARS11.10":{"question_mt":"Xi jfisser sinjal li jipprojbixxi dawra lejn il-lemin?","answers_mt":["L-ebda traffiku mil-lemin","It-triq fuq il-lemin magħluqa","Liwja fuq il-lemin","Ma tistax iddur lejn il-lemin"],"explanation_mt":"Dawra lejn il-lemin hija pprojbita."},"CARS10.21":{"question_mt":"Qed toqrob lejn salib it-toroq traffikuż b'diversi korsiji u marki tal-karreġġjata. Fl-aħħar mument tinduna li qiegħed fil-korsija ħażina. X'għandek tagħmel?","answers_mt":["Tkompli f'dik il-korsija","Tuża sinjali ċari bl-id biex taqsam il-korsiji","Tieqaf sakemm iż-żona tkun vojta","Tipprova taqsam bil-forza"],"explanation_mt":"Tagħmilx tibdil tal-korsija f'daqqa jew mhux sigur. Kompli fil-korsija u kkoreġi r-rotta aktar tard."},"CARS10.22":{"question_mt":"Fejn tista' taqbeż fi triq b’direzzjoni waħda?","answers_mt":["Biss min-naħa tal-lemin","Il-qbiż mhux permess","Biss min-naħa tax-xellug","Jew min-naħa tal-lemin jew tax-xellug"],"explanation_mt":"Fi triq b’direzzjoni waħda, tista' taqbeż minn kwalunkwe naħa meta jkun sigur u legali."},"CARS10.23":{"question_mt":"Qed issuq fi triq b’korsija waħda b'postijiet ta’ mogħdija biss fuq il-lemin. Is-sewwieq warajk jixtieq jaqbżek. X'għandek tagħmel?","answers_mt":["Tidħol f'post ta’ mogħdija fuq il-lemin tiegħek","Tixgħel id-dwal ta’ emerġenza","Tistenna faċċata ta' post ta’ mogħdija fuq il-lemin tiegħek","Taċċellera biex titbiegħed"],"explanation_mt":"Stenna faċċata tal-post ta’ mogħdija sabiex il-vettura ta' warajk tkun tista' tużah biex taqbżek b'mod sigur."},"CARS10.24":{"question_mt":"Int fi triq wiesgħa biżżejjed għal vettura waħda biss. Karozza ġejja lejk. Liema ŻEWĠ azzjonijiet huma korretti?","answers_mt":["Tistenna faċċata ta' post ta’ mogħdija fuq ix-xellug tiegħek","Tidħol f'post ta’ mogħdija jekk il-vettura tiegħek tkun usa'","Iġġiegħel lis-sewwieq l-ieħor jagħmel marċ lura","Tistenna faċċata ta' post ta’ mogħdija fuq il-lemin tiegħek","Tidħol f'post ta’ mogħdija fuq ix-xellug tiegħek","Tidħol f'post ta’ mogħdija fuq il-lemin tiegħek"],"explanation_mt":"Uża post ta’ mogħdija fuq ix-xellug tiegħek, jew stenna faċċata ta' wieħed fuq il-lemin biex il-vettura ġejja tkun tista' tidħol fih."},"CARS10.25":{"question_mt":"Is-sinjali normalment jingħataw bl-indikaturi tad-direzzjoni u:","answers_mt":["Dwal tal-brejkijiet","Dwal ta' ġewwa","Dwal taċ-ċpar","Dwal tal-pożizzjoni"],"explanation_mt":"Id-dwal tal-brejkijiet jikkomunikaw li qed tnaqqas il-veloċità jew tieqaf."},"CARS10.26":{"question_mt":"Meta tibqa' sejjer dritt f'rotonda, meta għandek tagħti l-indikatur tax-xellug?","answers_mt":["Eżatt wara li tgħaddi l-ħruġ ta' qabel dak li se tieħu","Meta tkun qed toqrob lejn ir-rotonda","Tagħti l-indikatur tal-lemin meta toqrob","Ma tagħti indikatur fl-ebda ħin"],"explanation_mt":"Agħti l-indikatur tax-xellug wara li tgħaddi l-ħruġ immedjatament qabel dak li biħsiebek tieħu."},"CARS10.27":{"question_mt":"Liema vettura jista' jkollha bżonn tuża trajettorja differenti mis-soltu f'rotonda?","answers_mt":["Karozza tal-familja","Vann","Karozza sportiva","Vettura twila"],"explanation_mt":"Vetturi twal jistgħu jkollhom bżonn aktar spazju fit-triq u trajettorja usa' f'rotonda."},"CARS5.12":{"question_mt":"Wara li tkun xrobt ħafna alkoħol, għaliex m'għandekx issuq l-għada? Agħżel 2 tweġibiet.","answers_mt":["Il-konċentrazzjoni tiegħek tista' tibqa' affettwata ħafna","Tista' tkun għadek 'il fuq mil-limitu legali","Żgur tkun sew taħt il-limitu legali","Il-konċentrazzjoni tiegħek ma tkunx affettwata"],"explanation_mt":"L-alkoħol jista' jibqa' fil-ġisem għal ħafna sigħat, jaffettwa l-konċentrazzjoni u possibbilment iżommok 'il fuq mil-limitu legali."},"CARS5.13":{"question_mt":"X'parir għandek tagħti lil sewwieq li xorob ftit alkoħol f'festa?","answers_mt":["Jistenna ftit u jsuq lejn id-dar","Isuq lejn id-dar bil-mod","Imur id-dar bit-trasport pubbliku","Jixrob kafè qawwi u jsuq"],"explanation_mt":"L-għażla sigura hija li ma jsuqx u juża forma oħra ta' trasport."},"CARS5.14":{"question_mt":"Se tmur għal avveniment soċjali u trid issuq ftit wara. X'prekawzjoni għandek tieħu?","answers_mt":["Tixrob ħalib qabel l-alkoħol","Tixrob kafè wara l-alkoħol","Tevita l-alkoħol kompletament","Tevita li tixrob fuq stonku vojt"],"explanation_mt":"Jekk trid issuq, l-aktar għażla sigura hija li tevita l-alkoħol kompletament."},"CARS5.15":{"question_mt":"Għaddew tmien sigħat mill-aħħar xarba alkoħolika tiegħek. Liema ŻEWĠ dikjarazzjonijiet jistgħu xorta japplikaw?","answers_mt":["Ma jkollok l-ebda alkoħol fis-sistema tiegħek","Żgur tkun taħt il-limitu legali","Tista' tkun għadek mhux f'kundizzjoni li ssuq","Tista' tkun għadek 'il fuq mil-limitu legali"],"explanation_mt":"Tmien sigħat ma jiggarantixxux li int f'kundizzjoni tajba biex issuq jew li tkun taħt il-limitu legali."},"CARS5.16":{"question_mt":"It-tabib ordnalek mediċina. Għaliex għandek tistaqsi jekk hux sigur li ssuq?","answers_mt":["Tista' taffettwa biss is-smigħ tiegħek","Dejjem trid tinforma lill-assiguratur","Xi mediċini jistgħu jnaqqsu r-reazzjonijiet tiegħek","Il-mediċini dejjem itejbu r-reazzjonijiet"],"explanation_mt":"Xi mediċini jikkawżaw ngħas jew reazzjonijiet aktar bil-mod."},"CARS5.17":{"question_mt":"Mediċina ġagħlitek bi ngħas għal diversi jiem. Illum tħossok aħjar iżda għad trid teħodha. Meta għandek issuq?","answers_mt":["Jekk xi ħadd jivvjaġġa miegħek","Biss bil-lejl","Biss jekk il-vjaġġ ikun meħtieġ","Wara li tiċċekkja mat-tabib tiegħek"],"explanation_mt":"Iċċekkja mat-tabib tiegħek qabel issuq waqt li tkun qed tieħu mediċina li kkawżatlek ngħas."},"CARS5.18":{"question_mt":"Tabib jippreskrivi mediċina li x'aktarx taffettwa s-sewqan tiegħek. X'għandek tagħmel?","answers_mt":["Qatt taqbeż 30 km/h","Issuq biss ma' passiġġier","Issuqx int stess","Tevita biss toroq traffikużi"],"explanation_mt":"Issuqx meta mediċina x'aktarx tnaqqas il-kapaċità tiegħek li ssuq b'mod sigur."},"CARS6.2":{"question_mt":"Liema sinjal ta’ twissija ifisser li jista' jkun hemm nies mexjin tul it-triq?","answers_mt":["Persuni mexjin fit-triq","Ebda persuni mexjin","Tmiem iż-żona pedonali","Parkeġġ tal-iskola biss"],"explanation_mt":"Is-sinjal ta' twissija għall-persuni mexjin jindika li jista' jkun hemm nies mexjin fit-triq jew maġenbha."},"CARS6.4":{"question_mt":"Qed iddur lejn ix-xellug għal triq sekondarja u hemm persuni mexjin qed jaqsmu. X'għandek tagħmel?","answers_mt":["Tuża dwal ta’ emerġenza","Iddoqq il-ħorn","Tagħmlilhom sinjal biex ikomplu","Tistenna sakemm jaqsmu"],"explanation_mt":"Ċedi u stenna sakemm il-persuni mexjin ikunu qasmu b'mod sigur."},"CARS6.5":{"question_mt":"Qed iddur lejn ix-xellug f'salib it-toroq u persuni mexjin f'daqqa jibdew jaqsmu. X'għandek tagħmel?","answers_mt":["Iddoqq il-ħorn u tkompli","Tieqaf u tagħmlilhom sinjal biex jaqsmu","Tkompli waqt li tħallilhom spazju","Iċċedilhom"],"explanation_mt":"Persuni mexjin li diġà qed jaqsmu għandhom il-prijorità; ċedilhom."},"CARS6.10":{"question_mt":"Il-veduta tiegħek minn salib it-toroq hija limitata minn vetturi pparkjati. X'għandek tagħmel?","answers_mt":["Toħroġ mill-vettura u tħares","Iddoqq il-ħorn u toħroġ","Toħroġ malajr","Tieqaf, imbagħad timxi bil-mod 'il quddiem sakemm tkun tista' tara ċar"],"explanation_mt":"Wara li tieqaf, avvanza bil-mod sakemm ikollok veduta ċara."},"CARS6.11":{"question_mt":"Int quddiem nett f'kju qed tistenna biex iddur lejn il-lemin għal triq sekondarja. Għaliex għandek tiċċekkja l-mera tal-lemin eżatt qabel iddur?","answers_mt":["Biex tiċċekkja traffiku li qed joħroġ","Biex tiċċekkja għal vetturi li qed jaqbżuk","Biex tiċċekkja t-triq sekondarja","Biex tfittex persuni mexjin"],"explanation_mt":"Mutur jew vettura oħra tista' tkun qed taqbżek min-naħa tal-lemin."},"CARS6.13":{"question_mt":"F'qsim pedonali kkontrollat bid-dwal qed jidhru d-dwal aħmar u ambra. X'għandek tagħmel?","answers_mt":["Titlaq minnufih","Dejjem tistenna d-dawl aħdar","Iċċedi lin-nies li għadhom fuq il-qsim","Tagħti sinjal lin-nies biex jaqsmu"],"explanation_mt":"Anke meta s-sinjal ikun qed jinbidel, in-nies li għadhom fuq il-qsim għandhom jitħallew itemmu l-qsim."},"CARS6.14":{"question_mt":"Persuna b'diżabilità qed taqsam bil-mod f'qsim pedonali kkontrollat bid-dwal u d-dawl jinbidel għal aħdar. X'għandek tagħmel? Agħżel 2 tweġibiet.","answers_mt":["Issuq quddiem il-persuna","Timxi bil-mod 'il quddiem","Tħalli lill-persuna taqsam","Iddoqq il-ħorn","Tkun paċenzjuż","Issuq minn wara l-persuna"],"explanation_mt":"Ħalli lill-persuna tlesti l-qsim u ibqa' paċenzjuż."},"CARS6.15":{"question_mt":"Id-dwal jinbidlu għal aħdar iżda persuni mexjin anzjani għadhom f'nofs qsim pedonali kkontrollat bid-dwal. X'għandek tagħmel?","answers_mt":["Tixgħel u titfi l-fanali ta’ quddiem","Tgħolli r-revs tal-magna","Tagħmlilhom sinjal biex jgħaġġlu","Tistenna għax jistgħu jieħdu aktar ħin"],"explanation_mt":"Stenna bil-paċenzja sakemm ikunu temmew il-qsim."},"CARS6.16":{"question_mt":"Qrib vann tal-ġelat, liema periklu għandek tkun l-aktar attent għalih?","answers_mt":["Karozza pparkjata tista' tiċċaqlaq","Is-sewwieq tal-vann jista' joħroġ","Il-vann jista' jiċċaqlaq","Tifel jista' jiġri fit-triq"],"explanation_mt":"Tfal jistgħu jiġru fit-triq bla mistenni qrib vann tal-ġelat."},"CARS6.18":{"question_mt":"Ballun jaqbeż fit-triq minn bejn karozzi pparkjati. X'għandek tagħmel?","answers_mt":["Tieqaf u tagħti sinjal lit-tfal biex jaqsmu","Tkompli bl-istess veloċità u tixgħel u titfi d-dwal","Tnaqqas il-veloċità u tkun lest li tieqaf għat-tfal","Tkompli u ddoqq il-ħorn"],"explanation_mt":"Tifel jista' jiġri wara l-ballun, għalhekk naqqas il-veloċità u kun lest li tieqaf."},"CARS6.26":{"question_mt":"Qed issegwi sewwieq tal-mutur fi triq mhux lixxa. X'għandek tagħmel?","answers_mt":["Tħalli l-istess spazju bħas-soltu","Taqbżu minnufih","Tħalli spazju żejjed f'każ li jiddevja biex jevita ħofor fit-triq","Tħalli inqas spazju biex ikun jista' jarak"],"explanation_mt":"Wiċċ mhux uniformi jista' jġiegħel sewwieq tal-mutur jibdel id-direzzjoni f'daqqa."},"CARS6.33":{"question_mt":"Lil liema ŻEWĠ utenti tat-triq għandek tħalli spazju żejjed meta taqbiżhom?","answers_mt":["Vetturi tat-tindif tat-triq","Muturi","Tratturi","Roti"],"explanation_mt":"Muturi u roti huma vulnerabbli għar-riħ, difetti fit-triq u bidliet f'daqqa fid-direzzjoni."},"CARS6.34":{"question_mt":"Għaliex għandek tħalli spazju żejjed meta taqbeż sewwieq tal-mutur f'ġurnata bir-riħ?","answers_mt":["Ir-rikkieb jista' jsuq aktar malajr mis-soltu","Ir-riħ jista’ jimbotta lis-sewwieq tal-mutur lejn il-ġenb quddiemek","Ir-rikkieb jista' jieqaf f'daqqa","Ir-rikkieb jista' jdur f'daqqa"],"explanation_mt":"Riħ qawwi minn naħa jista' jimbotta mutur lejn il-ġenb."},"CARS6.35":{"question_mt":"Liema tip ta' vettura jiġi affettwat l-aktar minn riħ qawwi?","answers_mt":["Trakk b'ċisterna","Mutur","Karozza","Trattur"],"explanation_mt":"Il-muturi huma ħfief u esposti, għalhekk riħ qawwi jaffettwahom l-aktar."},"CARS6.36":{"question_mt":"Għaliex għandek tfittex b’mod partikolari sewwieqa tal-muturi u ċiklisti f’salib it-toroq?","answers_mt":["Jistgħu ma jarawkx iddur","Jistgħu jnaqqsu l-veloċità biex iħalluk iddur","Huma aktar diffiċli biex tarahom","Dejjem għandhom il-prijorità"],"explanation_mt":"Id-daqs iżgħar tagħhom jagħmilhom aktar faċli li ma tindunax bihom."},"CARS6.37":{"question_mt":"Qed tistenna biex toħroġ minn triq sekondarja. Għaliex għandek toqgħod attent ħafna għall-muturi?","answers_mt":["Il-muturi dejjem għandhom il-prijorità","Il-Pulizija spiss jużaw muturi","Il-muturi huma żgħar u diffiċli biex tarahom","Il-muturi dejjem aktar veloċi mill-karozzi"],"explanation_mt":"Muturi jistgħu jkunu moħbija minn traffiku ieħor jew oġġetti maġenb it-triq."},"CARS6.43":{"question_mt":"Għaliex is-sewwieqa tal-muturi spiss iħarsu minn fuq l-ispalla tal-lemin eżatt qabel iduru lejn il-lemin?","answers_mt":["Jgħinhom iżommu l-bilanċ","Il-muturi m'għandhomx mirja","Għandhom bżonn jisimgħu t-traffiku","Għandhom bżonn jiċċekkjaw it-traffiku fl-angolu mejjet tagħhom"],"explanation_mt":"Il-kontroll minn fuq l-ispalla juri traffiku moħbi fil-angolu mejjet."},"CARS6.47":{"question_mt":"Liema TLIET perikli jistgħu joħolqu s-sewwieqa tal-muturi f’kjuwijiet tat-traffiku?","answers_mt":["Jgħaddu qrib ħafna tal-karozza tiegħek","Isuqu b'fanali baxxi","Isuqu wieħed wara l-ieħor","Jgħaddu bejn il-korsiji","Jidħlu eżatt quddiemek"],"explanation_mt":"Is-sewwieqa tal-muturi jistgħu jgħaddu qrib ħafna, jgħaddu bejn il-korsiji u jidħlu eżatt quddiemek."},"CARS6.49":{"question_mt":"Qed issuq fi traffiku miexi bil-mod. Eżatt qabel tibdel korsija, x'għandek tagħmel?","answers_mt":["Tinżel għall-ewwel ger","Tagħti sinjal bl-id li qed tnaqqas il-veloċità","Iddoqq il-ħorn","Tfittex sewwieqa tal-muturi li qed jgħaddu bejn il-korsiji fit-traffiku"],"explanation_mt":"Is-sewwieqa tal-muturi jistgħu jgħaddu bejn il-korsiji u jistgħu jkunu moħbija fl-angoli mejta."},"CARS6.59":{"question_mt":"Ikollok ħabta waqt li l-karozza tiegħek tkun miexja. X’inhi l-ewwel ħaġa importanti li trid tagħmel?","answers_mt":["Iċċempel lill-kumpanija tal-assigurazzjoni","Iċċempel lis-servizzi tal-emerġenza","Tieqaf fuq il-post","Tieqaf biss jekk xi ħadd ikun imweġġa'"],"explanation_mt":"Trid tieqaf fuq il-post tal-ħabta."},"CARS6.63":{"question_mt":"Karozza tolqot persuna miexja b'veloċità ta' 60 km/h. X'inhu r-riżultat probabbli?","answers_mt":["Il-persuna miexja probabbilment tgħix","Il-persuna miexja żgur tgħix","Il-persuna miexja probabbilment tmut","Il-persuna miexja żgur tmut"],"explanation_mt":"Il-probabbiltà ta' korriment fatali hija għolja ħafna b'60 km/h."},"CARS6.64":{"question_mt":"Bil-lejl id-dwal tal-vettura warajk jgħammxuk. X'għandek tagħmel?","answers_mt":["Tissettja l-mera fuq il-pożizzjoni kontra d-dija","Tixgħel u titfi d-dwal ta’ wara","Tibbrejkja f’daqqa","Taġġusta l-mera biex tgħammex lis-sewwieq l-ieħor"],"explanation_mt":"Uża l-pożizzjoni kontra d-dija tal-mera ta’ ġewwa."},"CARS7.1":{"question_mt":"It-triq hija mxarrba u tiżloq. Għaliex sewwieq tal-mutur jista' jiddevja madwar għotjien tad-drenaġġ f'liwja?","answers_mt":["Biex tevita li ttajjar ilma fuq persuni mexjin","Biex tużahom bħala punti ta’ riferiment fil-liwja","Biex tevita titqib","Biex tevita li l-mutur jiżloq fuq l-għotjien tal-metall"],"explanation_mt":"Għotjien tal-metall imxarrbin jistgħu jkunu jiżolqu ħafna għall-muturi."},"CARS11.70":{"question_mt":"Qed tistenna f'salib it-toroq f'forma ta' T. Vettura ġejja mil-lemin bl-indikatur tax-xellug iteptep. X'għandek tagħmel?","answers_mt":["Toħroġ bil-mod","Tistenna sakemm il-vettura tibda ddur","Toħroġ qabel ma tasal fis-salib it-toroq","Toħroġ u taċċellera b'saħħa"],"explanation_mt":"Tiddependix biss fuq l-indikatur; stenna sakemm il-vettura tibda ddur."},"CARS11.73":{"question_mt":"X'inhu l-limitu massimu tal-veloċità f'żona mibnija sakemm ma jkunx indikat mod ieħor?","answers_mt":["60 km/h","40 km/h","50 km/h","30 km/h"],"explanation_mt":"Il-limitu normali f’żona mibnija huwa 50 km/h sakemm is-sinjali ma jindikawx mod ieħor."},"CARS12.3":{"question_mt":"Qabel issuq vettura ta' persuna oħra, x'għandek tiżgura?","answers_mt":["Li d-dokumenti tal-assigurazzjoni jkunu fil-vettura","Li l-vettura tiegħek stess tkun assigurata","Li l-vettura tkun assigurata biex tkun tista’ ssuqha int","Li s-sid ikollu kopertura ta’ responsabbiltà lejn terzi"],"explanation_mt":"Trid tkun kopert speċifikament biex issuq dik il-vettura."},"CARS12.4":{"question_mt":"X'inhi l-kopertura minima legali tal-assigurazzjoni meħtieġa biex issuq fit-toroq pubbliċi?","answers_mt":["Kopertura għal korriment personali","Kopertura komprensiva sħiħa","Responsabbiltà lejn terzi, nar u serq","Responsabbiltà lejn terzi biss"],"explanation_mt":"L-assigurazzjoni ta’ responsabbiltà lejn terzi hija l-minimu legali."},"CARS12.7":{"question_mt":"Liema TLIET affarijiet għandek bżonn qabel tkun tista' ssuq legalment?","answers_mt":["Kopertura xierqa tal-assigurazzjoni","Manwal tal-vettura","Kopertura għall-ħsara","Diska valida tat-taxxa tat-triq u murija","Liċenzja tas-sewqan valida u ffirmata","Prova tal-identità"],"explanation_mt":"Għandek bżonn assigurazzjoni valida, taxxa tat-triq valida u liċenzja tas-sewqan valida."},"CARS11.30":{"question_mt":"Għal xiex huma s-sinjali triangolari?","answers_mt":["Biex jagħtu twissijiet","Biex jagħtu direzzjonijiet","Biex jagħtu ordnijiet","Biex jagħtu informazzjoni"],"explanation_mt":"Sinjali tat-triq triangolari ġeneralment huma sinjali ta' twissija."},"CARS11.34":{"question_mt":"Liema ERBA' minn dawn jiġu indikati b'sinjal tat-triq triangolari?","answers_mt":["Dritt biss","Tfal qed jaqsmu","Salib it-toroq f’forma ta’ T","It-triq tidjieq","Mina quddiem","Veloċità minima"],"explanation_mt":"Tfal qed jaqsmu, salib it-toroq f'forma ta' T, triq li tidjieq u mina quddiem huma sitwazzjonijiet ta' twissija murija b'sinjali triangolari."},"CARS11.55":{"question_mt":"Qed toqrob lejn dawl tat-traffiku aħmar. Is-sinjal se jinbidel minn aħmar għal:","answers_mt":["Aħmar u ambra, imbagħad aħdar","Aħdar u ambra, imbagħad aħdar","Ambra, imbagħad aħdar","Aħdar, imbagħad ambra"],"explanation_mt":"Is-sekwenza normali hija aħmar, imbagħad aħmar u ambra flimkien, imbagħad aħdar."},"CARS11.56":{"question_mt":"Dawl tat-traffiku aħmar ifisser:","answers_mt":["Tkompli b'attenzjoni","Tieqaf jekk tista' tibbrejkja b'mod sigur","Trid tieqaf u tistenna wara l-linja ta’ waqfien","Tista' ddur lejn ix-xellug jekk ikun sigur"],"explanation_mt":"Sinjal aħmar jitlob li tieqaf u tistenna wara l-linja ta’ waqfien."},"CARS11.57":{"question_mt":"Fid-dwal tat-traffiku, dawl ambra waħdu jfisser:","answers_mt":["Mur jekk l-ebda persuna miexja ma tkun qed taqsam","Mur jekk it-triq tkun vojta","Ipprepara biex titlaq","Ipprepara biex tieqaf fil-linja ta’ waqfien"],"explanation_mt":"Id-dawl ambra jfisser li għandek tieqaf fil-linja ta’ waqfien, sakemm ma jkunx perikoluż li tagħmel dan għax tkun qrib wisq."},"CARS11.58":{"question_mt":"Dawl tat-traffiku aħmar ifisser:","answers_mt":["Trid tieqaf wara l-linja bajda tal-waqfien","Trid tnaqqas il-veloċità u tipprepara biex tieqaf jekk it-traffiku beda jaqsam","Tista' ddur lejn ix-xellug jekk ikun sigur","Tista' tibqa' sejjer dritt jekk ma jkunx hemm traffiku ieħor"],"explanation_mt":"Aħmar ifisser li trid tieqaf wara l-linja bajda tal-waqfien."},"CARS4.1":{"question_mt":"Jekk il-karozza tiegħek għandha brejkijiet ABS u trid tieqaf f'emerġenza, x'għandek tagħmel?","answers_mt":["Tapplika l-brejk tal-idejn biex tnaqqas id-distanza ta' waqfien","Tagħfas il-pedala tal-brejk malajr u b'saħħa sakemm tieqaf","Tibqa' tagħfas u terħi il-pedala tal-brejk malajr","Tibbrejkja b'mod normali u tevita li ddawwar l-istering"],"explanation_mt":"B'ABS, agħfas il-brejk b'saħħa u żommu magħfus waqt li tidderieġi jekk ikun meħtieġ."},"CARS4.2":{"question_mt":"Il-brejkijiet ABS inaqqsu l-probabbiltà ta’ żliq b’mod partikolari meta:","answers_mt":["Issuq fuq wiċċ tajjeb tat-triq","Tibbrejkja waqt sewqan normali","Tibbrejkja f'emerġenza","Tinżel għoljiet weqfin"],"explanation_mt":"ABS huwa partikolarment utli waqt ibbrejkjar ta’ emerġenza."},"CARS4.3":{"question_mt":"Vetturi mgħammra bi brejkijiet ABS:","answers_mt":["M'għandhomx brejk tal-idejn","Jistgħu jiġu diretti waqt l-ibbrejkjar","Jaċċelleraw ħafna aktar malajr","Ma jistgħux jiżolqu"],"explanation_mt":"ABS jgħin biex jinżamm il-kontroll tal-istering waqt ibbrejkjar qawwi."},"CARS4.4":{"question_mt":"Il-brejkijiet ABS jistgħu ma jaħdmux b'mod effettiv kif mistenni jekk il-wiċċ tat-triq ikun: Agħżel 2 tweġibiet.","answers_mt":["Sod","Maħlul","Tajjeb","Niexef","Imxarrab"],"explanation_mt":"Wiċċ maħlul jew imxarrab jista' jnaqqas il-qabda tat-tajers u l-effettività tal-ABS."},"CARS4.12":{"question_mt":"X'inhi l-aktar raġuni komuni għaliex karozza tiżloq?","answers_mt":["Persuni mexjin","Żball tas-sewwieq","Vetturi oħra","Tajers mikulin"],"explanation_mt":"Il-biċċa l-kbira tal-każijiet ta' żliq jiġu kkawżati minn veloċità, istering jew ibbrejkjar mhux xierqa mis-sewwieq."},"CARS4.13":{"question_mt":"Meta tibbrejkja b'saħħa f'linja dritta, il-biċċa l-kbira tal-piż tal-vettura jiġi trasferit fuq:","answers_mt":["Ir-roti ta' quddiem","Ir-roti tal-lemin","Ir-roti tax-xellug","Ir-roti ta' wara"],"explanation_mt":"Ibbrejkjar qawwi jittrasferixxi l-piż 'il quddiem fuq ir-roti ta' quddiem."},"CARS4.15":{"question_mt":"Saqt il-karozza tiegħek minn ġo għargħar. X'inhi l-ewwel ħaġa li għandek tagħmel?","answers_mt":["Tixgħel il-wajpers tal-ħġieġa ta’ quddiem","Tieqaf u tnixxef il-brejkijiet","Tieqaf u tiċċekkja t-tajers","Tittestja l-brejkijiet"],"explanation_mt":"Ittestja l-brejkijiet bil-mod wara li tgħaddi mill-ilma għax jistgħu jkunu inqas effettivi."},"CARS8.36":{"question_mt":"Tara vettura ġejja lejk fi triq dejqa b’korsija waħda. X'għandek tagħmel?","answers_mt":["Tixgħel id-dwal ta’ emerġenza","Tagħmel waqfien ta’ emerġenza","Tieqaf f'post ta’ mogħdija","Tagħmel marċ lura sat-triq prinċipali"],"explanation_mt":"Uża post ta’ mogħdija biex il-vetturi jkunu jistgħu jgħaddu b'mod sigur."},"CARS9.1":{"question_mt":"Hekk kif tidħol f'karreġġjata doppja, fejn normalment għandek tqiegħed il-vettura?","answers_mt":["Fil-korsija tan-nofs","Taġġusta mill-ġdid il-mirja","Tipprova taqbeż","Fil-korsija tax-xellug"],"explanation_mt":"Żomm fuq ix-xellug sakemm ma tkunx qed taqbeż."},"CARS9.2":{"question_mt":"Meta tidħol f'karreġġjata doppja, x'għandek dejjem tagħmel?","answers_mt":["Tieqaf qabel tidħol","Tieqaf fit-tarf tal-korsija tal-aċċellerazzjoni","Tuża l-korsija ta’ emerġenza","Iċċedi lit-traffiku li diġà jinsab fil-karreġġjata"],"explanation_mt":"It-traffiku li diġà jinsab fil-karreġġjata għandu l-prijorità."},"CARS9.3":{"question_mt":"X'inhi regola fundamentali meta ssuq f'karreġġjata doppja?","answers_mt":["Żomm 'il fuq minn 50 km/h","Żomm fil-korsija tax-xellug sakemm ma tkunx qed taqbeż","Aqbeż minn kwalunkwe naħa li tkun vojta","Uża l-korsija bl-inqas traffiku"],"explanation_mt":"Normalment żomm fuq ix-xellug u uża korsiji oħra biss meta tkun qed taqbeż."},"CARS9.4":{"question_mt":"Vettura quddiemek tixgħel għal ftit id-dwal ta’ emerġenza f’karreġġjata doppja. Xi jfisser dan?","answers_mt":["Hemm kontroll tal-veloċità mill-pulizija","Il-vettura se tibdel korsija","It-traffiku quddiem qed inaqqas jew jieqaf f'daqqa","Is-sewwieq iridek taqbżu"],"explanation_mt":"Id-dwal ta’ emerġenza jistgħu jwissu lit-traffiku ta’ wara dwar tnaqqis jew waqfien f’daqqa."},"CARS9.5":{"question_mt":"Trid tnaqqas il-veloċità malajr f'karreġġjata doppja minħabba periklu. X'għandek tagħmel?","answers_mt":["Tixgħel id-dwal ta’ emerġenza","Tixgħel u titfi l-fanali ta’ quddiem","Iddoqq il-ħorn","Tixgħel fanali għoljin"],"explanation_mt":"Uża d-dwal ta’ emerġenza biex tavża lit-traffiku warajk bil-periklu f'daqqa."},"CARS9.6":{"question_mt":"Liema vetturi normalment ikollhom dwal ambra li jteptpu? Agħżel 2 tweġibiet.","answers_mt":["Gwardja tal-kosta","Vetturi tal-manutenzjoni","Tim tat-trasfużjoni tad-demm","Vetturi ta’ rkupru wara ħsara","Karozza ta' tabib"],"explanation_mt":"Vetturi tal-manutenzjoni u vetturi ta’ rkupru wara ħsara normalment jużaw dwal ambra li jteptpu."},"LPTV2026.030":{"question_mt":"X’għandu jlesti sewwieq li jaħdem permezz ta’ pjattaforma meta jintalab?","answers_mt":["Verifika bir-rikonoxximent tal-wiċċ","Eżami prattiku tas-sewqan kull darba","Eżami VRT","Irċevuta tal-fjuwil"],"explanation_mt":"Is-sewwieqa għandhom ilestu l-verifika meħtieġa bir-rikonoxximent tal-wiċċ meta tintalab mill-pjattaforma."},"LPTV2026.032":{"question_mt":"X’għandu jibqa’ jkollu sewwieq LPTV waqt li jkun qed jopera vettura ħafifa għat-trasport tal-passiġġieri? Agħżel 2 tweġibiet.","answers_mt":["Liċenzja tas-sewqan valida","It-Tag xierqa tal-Permess tas-Sewwieq ta’ Transport Malta","Ċertifikat tat-tassimetru","Karta ta’ parkeġġ privat"],"explanation_mt":"Is-sewwieq għandu jkollu kemm liċenzja tas-sewqan valida kif ukoll it-Tag tal-Permess tas-Sewwieq applikabbli."},"LPTV2026.035":{"question_mt":"Ir-rekwiżiti tax-xogħol u l-mistrieħ japplikaw biss għal xogħol permezz ta’ pjattaforma?","answers_mt":["Iva","Le, japplikaw ukoll għal servizzi rranġati b'mod indipendenti","Biss għal servizzi SOV","Biss għal trasferimenti tal-ajruport"],"explanation_mt":"Il-limiti japplikaw kemm jekk is-servizzi jingħataw permezz ta' pjattaforma kif ukoll jekk jiġu rranġati b'mod indipendenti."},"LPTV2026.046":{"question_mt":"X'għandu juri l-arloġġ uffiċjali tal-parkeġġ?","answers_mt":["Il-ħin meta l-vettura ġiet ipparkjata","Il-ħin meta jispiċċa x-xogħol tas-sewwieq","Il-ħin tal-prenotazzjoni li jmiss","Id-data tas-servizz tal-vettura"],"explanation_mt":"L-arloġġ għandu jkun issettjat b'mod korrett biex juri l-ħin meta l-vettura ġiet ipparkjata."},"LPOINTS1.62":{"question_mt":"Għandek tobdi sinjal STOP anke meta ma tkun ġejja l-ebda vettura oħra?","answers_mt":["Le","Kultant","Iva","Biss bil-lejl"],"explanation_mt":"Sinjal STOP jitlob waqfien sħiħ anke meta t-triq tidher vojta."},"LPOINTS1.74":{"question_mt":"Xi jfisser sinjal 'Tużax il-ħorn'?","answers_mt":["Uża l-ħorn","Ebda baned li jimmarċjaw","Tużax il-ħorn","Parkeġġ tal-isptar"],"explanation_mt":"Is-sinjal jipprojbixxi l-użu tal-ħorn f'dik iż-żona."},"LPOINTS1.79":{"question_mt":"Jekk sinjal STOP jew sinjal ĊEDI ma jkollux marki tat-triq, x'għandek tagħmel?","answers_mt":["Tinjorah","Tieqaf jew iċċedi fl-aktar punt sigur minn fejn tista' tara ċar","Iddoqq il-ħorn u tkompli","Tieqaf ħames metri wara s-salib it-toroq"],"explanation_mt":"Trid tobdi s-sinjal u tqiegħed il-vettura fl-aktar punt sigur minn fejn tkun tista' tara ċar u tkompli b'mod sigur."}};
